const queryClient = new QueryClient();
const today = new Date().toISOString().slice(0, 10);
const inviteLink = (roomId: string) => `${window.location.origin}/room/${roomId}`;
const labelColors = ['#6f9f8b', '#d79b4c', '#9a7bb5', '#d26f67', '#5d8fb5', '#c17b55'];
const toDate = (value: string) => new Date(`${value}T12:00:00`);
const addDays = (value: string, amount: number) => {
  const date = toDate(value);
  date.setDate(date.getDate() + amount);
  return date.toISOString().slice(0, 10);
};
const mondayOf = (value: string) => {
  const date = toDate(value);
  const day = date.getDay();
  return addDays(value, day === 0 ? -6 : 1 - day);
};
const weekStart = mondayOf(today);
const formatDate = (value: string) => toDate(value).toLocaleDateString(undefined, { month: 'short', day: 'numeric' });
const weekRange = (start: string) => `${formatDate(start)} – ${formatDate(addDays(start, 6))}`;

function initials(name: string) {
  return name.split(' ').map((part) => part[0]).join('').slice(0, 2).toUpperCase();
}

function Avatar({ player, size = 'md' }: { player?: Player | null; size?: 'sm' | 'md' | 'lg' }) {
  const sizes = { sm: 'h-7 w-7 text-[10px]', md: 'h-9 w-9 text-xs', lg: 'h-12 w-12 text-sm' };
  return <div data-testid={player ? `avatar-${player.id}` : 'avatar-empty'} className={`${sizes[size]} grid shrink-0 place-items-center rounded-full border-2 border-background bg-[#d7c6a1] font-extrabold text-[#302f48] shadow-sm`}>{player ? initials(player.name) : '?'}</div>;
}

function Button({ children, className = '', variant = 'primary', ...props }: React.ButtonHTMLAttributes<HTMLButtonElement> & { variant?: 'primary' | 'secondary' | 'ghost' | 'danger' }) {
  const styles = {
    primary: 'bg-[#f7ca56] text-[#24243b] shadow-[0_3px_0_#c4962b] hover:-translate-y-0.5 hover:shadow-[0_5px_0_#c4962b]',
    secondary: 'bg-[#302f48] text-[#fff7e8] shadow-[0_3px_0_#1d1d31] hover:-translate-y-0.5',
    ghost: 'border border-[#d9cfbd] bg-transparent text-[#3e3a4e] hover:bg-[#ebe3d4]',
    danger: 'bg-[#f3d5d0] text-[#9f433e] hover:bg-[#efc3bd]',
  };
  return <button {...props} className={`inline-flex items-center justify-center gap-2 rounded-xl px-4 py-2.5 text-sm font-bold transition-all duration-200 disabled:cursor-not-allowed disabled:opacity-50 ${styles[variant]} ${className}`} />;
}

function LoadingState({ label = 'Finding the next landmark...' }: { label?: string }) {
  return <div className="flex min-h-[300px] items-center justify-center"><div className="flex flex-col items-center gap-3 text-center text-muted-foreground"><div className="h-10 w-10 animate-pulse-soft rounded-full border-4 border-[#f7ca56] border-t-transparent" /><p className="text-sm font-semibold">{label}</p></div></div>;
}

function ErrorState({ retry }: { retry?: () => void }) {
  return <div className="mx-auto flex max-w-md flex-col items-center justify-center gap-4 py-20 text-center"><div className="grid h-14 w-14 place-items-center rounded-2xl bg-[#f3d5d0] text-[#9f433e]"><Info /></div><h2 className="font-display text-2xl font-bold">The road went quiet</h2><p className="text-sm text-muted-foreground">We couldn't reach your shared journey. Try again, or check your invite.</p>{retry && <Button variant="ghost" onClick={retry} data-testid="button-retry"><RefreshCw className="h-4 w-4" /> Try again</Button>}</div>;
}

function EmptyState({ icon: Icon, title, body, action }: { icon: typeof Compass; title: string; body: string; action?: ReactNode }) {
  return <div className="texture-grid flex min-h-[260px] flex-col items-center justify-center rounded-2xl border border-dashed border-[#d7cbb8] bg-[#f8f1e5] p-8 text-center"><div className="mb-4 grid h-14 w-14 place-items-center rounded-2xl bg-[#ece1cf] text-[#7f7664]"><Icon /></div><h3 className="font-display text-xl font-bold">{title}</h3><p className="mt-2 max-w-sm text-sm leading-6 text-muted-foreground">{body}</p>{action && <div className="mt-5">{action}</div>}</div>;
}

function HomePage() {
  const [, setLocation] = useLocation();
  const createRoom = useCreateRoom();
  const joinRoom = useJoinRoom();
  const [mode, setMode] = useState<'create' | 'join'>('create');
  const [name, setName] = useState('');
  const [roomName, setRoomName] = useState('');
  const [code, setCode] = useState('');
  const [error, setError] = useState('');
  const submit = (event: FormEvent) => {
    event.preventDefault(); setError('');
    if (!name.trim()) return setError('Tell us what your friend should call you.');
    if (mode === 'create') {
      if (!roomName.trim()) return setError('Give your journey a name.');
      createRoom.mutate({ data: { name: roomName.trim(), playerName: name.trim() } }, {
        onSuccess: (room) => { localStorage.setItem('quest-road-room', room.id); localStorage.setItem('quest-road-player', room.host.id); setLocation(`/room/${room.id}`); },
        onError: () => setError('That trail could not be opened. Try again in a moment.'),
      });
    } else {
      if (!code.trim()) return setError('Enter the invite code from your friend.');
      joinRoom.mutate({ roomId: code.trim(), data: { code: code.trim(), playerName: name.trim() } }, {
        onSuccess: (room) => { localStorage.setItem('quest-road-room', room.id); localStorage.setItem('quest-road-player', room.guest?.id ?? ''); setLocation(`/room/${room.id}`); },
        onError: () => setError('We could not find that invite. Check the code and try again.'),
      });
    }
  };
  const pending = createRoom.isPending || joinRoom.isPending;
  return <main className="min-h-[100dvh] overflow-hidden bg-[#24243b] text-[#fff7e8]">
    <div className="absolute inset-0 opacity-40" style={{ backgroundImage: 'radial-gradient(circle at 75% 15%, #f7ca56 0, transparent 17%), radial-gradient(circle at 15% 82%, #476b67 0, transparent 24%)' }} />
    <div className="relative mx-auto flex min-h-[100dvh] max-w-7xl flex-col px-5 py-5 sm:px-10 sm:py-8">
      <header className="flex items-center justify-between"><Link href="/" className="flex items-center gap-3" data-testid="link-home-logo"><span className="grid h-10 w-10 place-items-center rounded-xl bg-[#f7ca56] text-[#24243b] shadow-[0_4px_0_#c4962b]"><Compass className="h-5 w-5" /></span><span className="font-display text-lg font-bold tracking-tight">Quest Road</span></Link><span className="hidden items-center gap-2 text-xs font-bold tracking-[.18em] text-[#aaa9ba] uppercase sm:flex"><span className="h-2 w-2 rounded-full bg-[#78b29d]" /> Two seats. One story.</span></header>
      <div className="grid flex-1 items-center gap-12 py-12 lg:grid-cols-[1fr_440px] lg:gap-20">
        <section className="max-w-2xl animate-rise"><p className="mb-6 font-mono-ui text-xs font-medium tracking-[.24em] text-[#f7ca56] uppercase">A cooperative browser adventure</p><h1 className="font-display text-5xl font-bold leading-[.98] tracking-[-.05em] sm:text-7xl">Make ordinary days<br /><span className="text-[#f7ca56]">worth the detour.</span></h1><p className="mt-7 max-w-lg text-base leading-7 text-[#bdbaca] sm:text-lg">You bring the quests. Your favorite person brings theirs. Walk the road together, one small win at a time.</p><div className="mt-10 flex flex-wrap gap-6 text-sm text-[#d7d3df]"><span className="flex items-center gap-2"><UsersRound className="h-4 w-4 text-[#f7ca56]" /> Exactly two players</span><span className="flex items-center gap-2"><ShieldCheck className="h-4 w-4 text-[#78b29d]" /> Your data stays yours</span></div></section>
        <section className="animate-rise rounded-3xl bg-[#fff7e8] p-6 text-[#24243b] shadow-[0_22px_60px_rgba(9,10,28,.35)] sm:p-8" style={{ animationDelay: '.12s' }}>
          <div className="mb-7 flex gap-1 rounded-xl bg-[#eee5d5] p-1"><button onClick={() => setMode('create')} data-testid="button-mode-create" className={`flex-1 rounded-lg px-3 py-2 text-sm font-bold transition ${mode === 'create' ? 'bg-[#302f48] text-[#fff7e8]' : 'text-[#797388]'}`}>Start a journey</button><button onClick={() => setMode('join')} data-testid="button-mode-join" className={`flex-1 rounded-lg px-3 py-2 text-sm font-bold transition ${mode === 'join' ? 'bg-[#302f48] text-[#fff7e8]' : 'text-[#797388]'}`}>Join a friend</button></div>
          <div className="mb-6"><h2 className="font-display text-2xl font-bold">{mode === 'create' ? 'Set the wheels in motion' : 'Pick up the thread'}</h2><p className="mt-1 text-sm text-[#797388]">{mode === 'create' ? 'Name your shared corner of the world.' : 'Your friend’s invite code is the key.'}</p></div>
          <form onSubmit={submit} className="space-y-4">
            {mode === 'create' ? <label className="block text-sm font-bold">Journey name<input value={roomName} onChange={(e) => setRoomName(e.target.value)} placeholder="Sunday Side Quests" data-testid="input-room-name" className="mt-2 w-full rounded-xl border border-[#d9cfbd] bg-[#fbf5eb] px-4 py-3 outline-none transition placeholder:text-[#ada596] focus:border-[#c4962b] focus:ring-2 focus:ring-[#f7ca56]/30" /></label> : <label className="block text-sm font-bold">Invite code<input value={code} onChange={(e) => setCode(e.target.value.toUpperCase())} maxLength={12} placeholder="ROAD-7K2M" data-testid="input-invite-code" className="mt-2 w-full rounded-xl border border-[#d9cfbd] bg-[#fbf5eb] px-4 py-3 font-mono-ui uppercase tracking-[.18em] outline-none transition placeholder:text-[#ada596] focus:border-[#c4962b] focus:ring-2 focus:ring-[#f7ca56]/30" /></label>}
            <label className="block text-sm font-bold">Your name<input value={name} onChange={(e) => setName(e.target.value)} placeholder="What should we call you?" data-testid="input-player-name" className="mt-2 w-full rounded-xl border border-[#d9cfbd] bg-[#fbf5eb] px-4 py-3 outline-none transition placeholder:text-[#ada596] focus:border-[#c4962b] focus:ring-2 focus:ring-[#f7ca56]/30" /></label>
            {error && <p data-testid="status-entry-error" className="rounded-lg bg-[#f3d5d0] px-3 py-2 text-sm font-semibold text-[#9f433e]">{error}</p>}
            <Button type="submit" disabled={pending} className="mt-2 w-full py-3.5" data-testid="button-submit-entry">{pending ? <Loader2 className="h-4 w-4 animate-spin" /> : <>{mode === 'create' ? 'Create the room' : 'Join the room'} <ArrowRight className="h-4 w-4" /></>}</Button>
          </form>
          <p className="mt-5 text-center text-xs text-[#928a7c]">No feed. No followers. Just the two of you.</p>
        </section>
      </div>
      <footer className="flex items-center justify-between border-t border-[#ffffff18] pt-5 text-xs text-[#858397]"><span>Made for the long way home.</span><span className="font-mono-ui">v0.1 / quiet mode</span></footer>
    </div>
  </main>;
}

const navItems = [
  { href: '/today', label: 'Today', icon: Target },
  { href: '/map', label: 'Journey map', icon: Map },
  { href: '/calendar', label: 'Calendar', icon: CalendarDays },
  { href: '/rewards', label: 'Reward shop', icon: Trophy },
  { href: '/together', label: 'Together', icon: UsersRound },
];

function Shell({ children, state }: { children: ReactNode; state?: GameState }) {
  const [location] = useLocation();
  const [open, setOpen] = useState(false);
  const meId = localStorage.getItem('quest-road-player') ?? '';
  const me = state?.players.find((player) => player.id === meId) ?? state?.players[0];
  return <div className="min-h-[100dvh] bg-[#f3ecdf] text-[#302f48]">
    <aside className={`fixed inset-y-0 left-0 z-30 flex w-[260px] flex-col bg-[#24243b] px-5 py-6 text-[#fff7e8] transition-transform duration-300 lg:translate-x-0 ${open ? 'translate-x-0' : '-translate-x-full'}`}>
      <Link href="/" onClick={() => setOpen(false)} className="mb-10 flex items-center gap-3 px-2" data-testid="link-shell-logo"><span className="grid h-9 w-9 place-items-center rounded-xl bg-[#f7ca56] text-[#24243b]"><Compass className="h-5 w-5" /></span><span className="font-display text-lg font-bold">Quest Road</span></Link>
      <div className="mb-7 rounded-2xl border border-[#ffffff12] bg-[#ffffff09] p-3"><div className="flex items-center gap-3"><Avatar player={me} /><div className="min-w-0"><p data-testid="text-sidebar-player" className="truncate text-sm font-bold">{me?.name ?? 'Wayfarer'}</p><p className="font-mono-ui text-[10px] text-[#aaa9ba]">{me ? `${me.coins} coins · ${me.xp} XP` : 'Finding your party'}</p></div></div>{me && <div className="mt-3 flex items-center gap-2 text-xs text-[#f7ca56]"><Zap className="h-3.5 w-3.5 fill-current" /> {me.streak} day trail streak</div>}</div>
      <nav className="space-y-1" aria-label="Main navigation">{navItems.map(({ href, label, icon: Icon }) => <Link key={href} href={href} onClick={() => setOpen(false)} data-testid={`link-nav-${label.toLowerCase().replaceAll(' ', '-')}`} className={`flex items-center gap-3 rounded-xl px-3 py-3 text-sm font-bold transition ${location === href ? 'bg-[#f7ca56] text-[#24243b]' : 'text-[#aaa9ba] hover:bg-[#ffffff0d] hover:text-[#fff7e8]'}`}><Icon className="h-[18px] w-[18px]" />{label}{location === href && <ChevronRight className="ml-auto h-4 w-4" />}</Link>)}</nav>
      <div className="mt-auto space-y-1"><Link href="/settings" onClick={() => setOpen(false)} data-testid="link-nav-settings" className={`flex items-center gap-3 rounded-xl px-3 py-3 text-sm font-bold transition ${location === '/settings' ? 'bg-[#ffffff12] text-[#fff7e8]' : 'text-[#aaa9ba] hover:bg-[#ffffff0d] hover:text-[#fff7e8]'}`}><Settings2 className="h-[18px] w-[18px]" />Settings</Link><div className="mt-4 border-t border-[#ffffff12] pt-4 text-[11px] leading-5 text-[#77768b]">A little progress,<br />shared on purpose.</div></div>
    </aside>
    {open && <button aria-label="Close menu" data-testid="button-close-menu" onClick={() => setOpen(false)} className="fixed inset-0 z-20 bg-[#24243b]/45 lg:hidden" />}
    <div className="lg:pl-[260px]"><header className="sticky top-0 z-10 flex h-[72px] items-center justify-between border-b border-[#ddd1bf] bg-[#f3ecdf]/90 px-5 backdrop-blur-md sm:px-8"><button onClick={() => setOpen(true)} data-testid="button-open-menu" className="rounded-lg p-2 text-[#302f48] hover:bg-[#e7ddcc] lg:hidden"><Menu className="h-5 w-5" /></button><div className="hidden items-center gap-2 text-xs font-bold text-[#858072] sm:flex"><span className="h-2 w-2 rounded-full bg-[#78b29d]" /> {state?.room.name ?? 'Your shared journey'}</div><div className="ml-auto flex items-center gap-3">{state && <div className="flex -space-x-2">{state.players.map((player) => <Avatar player={player} size="sm" key={player.id} />)}</div>}<Link href="/settings" data-testid="link-header-settings" className="grid h-9 w-9 place-items-center rounded-xl border border-[#d9cfbd] text-[#615c6d] hover:bg-[#e7ddcc]"><Settings2 className="h-4 w-4" /></Link></div></header><main className="mx-auto max-w-[1280px] px-5 py-7 sm:px-8 sm:py-10">{children}</main></div>
  </div>;
}

function useSharedState() {
  const roomId = localStorage.getItem('quest-road-room') ?? '';
  const query = useGetGameState(roomId, { query: { enabled: Boolean(roomId), queryKey: getGetGameStateQueryKey(roomId), refetchInterval: 12000 } });
  return { ...query, roomId };
}

function PageHeader({ eyebrow, title, body, action }: { eyebrow: string; title: string; body: string; action?: ReactNode }) {
  return <div className="mb-8 flex flex-col justify-between gap-5 sm:flex-row sm:items-end"><div><p className="mb-2 font-mono-ui text-[11px] font-medium tracking-[.2em] text-[#9a7a2b] uppercase">{eyebrow}</p><h1 className="font-display text-4xl font-bold tracking-[-.045em] sm:text-5xl">{title}</h1><p className="mt-3 max-w-xl text-sm leading-6 text-muted-foreground">{body}</p></div>{action}</div>;
}

function MissingRoom() {
  return <EmptyState icon={Link2} title="No journey selected" body="Create a room or join a friend first. Your current journey will stay saved on this device." action={<Link href="/" data-testid="link-start-journey"><Button>Find your road <ArrowRight className="h-4 w-4" /></Button></Link>} />;
}

function QuestRow({ quest, owner, onComplete, onDelete, onEdit }: { quest: Quest; owner?: Player; onComplete: () => void; onDelete: () => void; onEdit: () => void }) {
  const complete = quest.status === 'completed';
  return <article data-testid={`card-quest-${quest.id}`} className={`group rounded-2xl border bg-[#fffaf1] p-4 transition-all ${complete ? 'border-[#c9d9cd] bg-[#f3f8f3]' : 'border-[#dfd3c1] hover:-translate-y-0.5 hover:border-[#c4962b] hover:shadow-route'}`}><div className="flex items-start gap-3"><button onClick={onComplete} aria-label={complete ? 'Reopen quest' : 'Complete quest'} data-testid={`button-complete-quest-${quest.id}`} className={`mt-0.5 grid h-6 w-6 shrink-0 place-items-center rounded-full border-2 transition ${complete ? 'border-[#579477] bg-[#579477] text-white' : 'border-[#b7aa95] hover:border-[#c4962b] hover:bg-[#f7ca56]'}`}>{complete && <Check className="h-3.5 w-3.5" />}</button><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><h3 className={`font-bold ${complete ? 'text-[#74897b] line-through' : ''}`}>{quest.title}</h3><span className={`rounded-md px-2 py-0.5 text-[10px] font-extrabold uppercase tracking-wide ${quest.priority === 'major' ? 'bg-[#f3d5d0] text-[#a14f48]' : quest.priority === 'medium' ? 'bg-[#eee2c6] text-[#93752c]' : 'bg-[#dce9e2] text-[#4d8067]'}`}>{quest.priority}</span></div>{quest.notes && <p className="mt-1 line-clamp-2 text-xs leading-5 text-muted-foreground">{quest.notes}</p>}<div className="mt-3 flex flex-wrap items-center gap-3 text-[11px] font-semibold text-muted-foreground"><span className="flex items-center gap-1"><CalendarDays className="h-3.5 w-3.5" /> {quest.dueDate === today ? 'Today' : new Date(`${quest.dueDate}T12:00`).toLocaleDateString(undefined, { month: 'short', day: 'numeric' })}</span><span className="flex items-center gap-1 text-[#ad7d1e]"><Gem className="h-3.5 w-3.5" /> +{quest.coinValue} coins</span><span className="flex items-center gap-1 text-[#6685a0]"><Star className="h-3.5 w-3.5" /> +{quest.xpValue} XP</span>{owner && <span className="ml-auto flex items-center gap-1.5"><Avatar player={owner} size="sm" /> {owner.name}</span>}</div></div><div className="flex gap-1 opacity-0 transition group-hover:opacity-100"><button onClick={onEdit} data-testid={`button-edit-quest-${quest.id}`} className="rounded-lg p-2 text-muted-foreground hover:bg-[#eee2d2] hover:text-foreground"><Settings2 className="h-4 w-4" /></button><button onClick={onDelete} data-testid={`button-delete-quest-${quest.id}`} className="rounded-lg p-2 text-muted-foreground hover:bg-[#f3d5d0] hover:text-[#a14f48]"><X className="h-4 w-4" /></button></div></div></article>;
}

function QuestForm({ state, editQuest, onClose }: { state: GameState; editQuest?: Quest; onClose: () => void }) {
  const roomId = state.room.id; const meId = localStorage.getItem('quest-road-player') ?? state.players[0]?.id ?? '';
  const create = useCreateQuest(); const update = useUpdateQuest(); const qc = useQueryClient();
  const [title, setTitle] = useState(editQuest?.title ?? ''); const [notes, setNotes] = useState(editQuest?.notes ?? ''); const [dueDate, setDueDate] = useState(editQuest?.dueDate ?? today); const [priority, setPriority] = useState<QuestPriority>(editQuest?.priority ?? 'small');
  const save = (e: FormEvent) => { e.preventDefault(); const data = { ownerId: meId, title: title.trim(), notes: notes.trim(), dueDate, priority }; if (!data.title) return; const done = () => { qc.invalidateQueries({ queryKey: getGetGameStateQueryKey(roomId) }); onClose(); }; if (editQuest) update.mutate({ roomId, questId: editQuest.id, data }, { onSuccess: done }); else create.mutate({ roomId, data }, { onSuccess: done }); };
  const pending = create.isPending || update.isPending;
  return <div className="fixed inset-0 z-50 grid place-items-center bg-[#24243b]/55 p-4" role="dialog" aria-modal="true"><div className="w-full max-w-lg rounded-3xl bg-[#fffaf1] p-6 shadow-[0_24px_70px_rgba(20,20,40,.25)] sm:p-8"><div className="mb-6 flex items-start justify-between"><div><p className="font-mono-ui text-[10px] tracking-[.2em] text-[#9a7a2b] uppercase">{editQuest ? 'Edit quest' : 'New quest'}</p><h2 className="mt-1 font-display text-2xl font-bold">{editQuest ? 'Tune the route' : 'Add a small adventure'}</h2></div><button onClick={onClose} data-testid="button-close-quest-form" className="rounded-lg p-2 text-muted-foreground hover:bg-[#eee2d2]"><X className="h-5 w-5" /></button></div><form onSubmit={save} className="space-y-4"><label className="block text-sm font-bold">Quest title<input autoFocus value={title} onChange={(e) => setTitle(e.target.value)} placeholder="Leave work on time" data-testid="input-quest-title" className="mt-2 w-full rounded-xl border border-[#d9cfbd] bg-[#fffdf8] px-4 py-3 outline-none focus:border-[#c4962b] focus:ring-2 focus:ring-[#f7ca56]/30" /></label><label className="block text-sm font-bold">A note <span className="font-normal text-muted-foreground">(optional)</span><textarea value={notes} onChange={(e) => setNotes(e.target.value)} rows={3} placeholder="What would make this feel done?" data-testid="input-quest-notes" className="mt-2 w-full resize-none rounded-xl border border-[#d9cfbd] bg-[#fffdf8] px-4 py-3 text-sm outline-none focus:border-[#c4962b] focus:ring-2 focus:ring-[#f7ca56]/30" /></label><div className="grid gap-4 sm:grid-cols-2"><label className="block text-sm font-bold">Due date<input type="date" value={dueDate} onChange={(e) => setDueDate(e.target.value)} data-testid="input-quest-due-date" className="mt-2 w-full rounded-xl border border-[#d9cfbd] bg-[#fffdf8] px-4 py-3 text-sm outline-none focus:border-[#c4962b]" /></label><label className="block text-sm font-bold">Trail weight<select value={priority} onChange={(e) => setPriority(e.target.value as QuestPriority)} data-testid="select-quest-priority" className="mt-2 w-full rounded-xl border border-[#d9cfbd] bg-[#fffdf8] px-4 py-3 text-sm outline-none focus:border-[#c4962b]"><option value="small">Small · 10 coins</option><option value="medium">Medium · 20 coins</option><option value="major">Major · 30 coins</option></select></label></div><Button type="submit" disabled={pending || !title.trim()} data-testid="button-save-quest" className="mt-2 w-full">{pending ? <Loader2 className="h-4 w-4 animate-spin" /> : editQuest ? 'Save changes' : 'Pin this quest'}</Button></form></div></div>;
}

function TodayPage({ state }: { state: GameState }) {
  const [form, setForm] = useState(false); const [edit, setEdit] = useState<Quest>(); const qc = useQueryClient(); const complete = useSetQuestCompleted(); const remove = useDeleteQuest(); const meId = localStorage.getItem('quest-road-player') ?? state.players[0]?.id ?? ''; const me = state.players.find((p) => p.id === meId) ?? state.players[0]; const other = state.players.find((p) => p.id !== me?.id);
   const mine = state.quests.filter((q) => q.ownerId === me?.id); const myDone = mine.filter((q) => q.status === 'completed').length; const nextUp = mine.filter((q) => q.status !== 'completed').sort((a, b) => (a.dueDate ?? '9999-12-31').localeCompare(b.dueDate ?? '9999-12-31')); const finish = (quest: Quest) => complete.mutate({ roomId: state.room.id, questId: quest.id, data: { ownerId: quest.ownerId, completed: quest.status !== 'completed' } }, { onSuccess: () => qc.invalidateQueries({ queryKey: getGetGameStateQueryKey(state.room.id) }) }); const del = (quest: Quest) => { if (window.confirm('Remove this quest from the road?')) remove.mutate({ roomId: state.room.id, questId: quest.id, data: { ownerId: quest.ownerId } }, { onSuccess: () => qc.invalidateQueries({ queryKey: getGetGameStateQueryKey(state.room.id) }) }); };
  return <><PageHeader eyebrow={state.weekLabel} title={`Good morning, ${me?.name ?? 'wayfarer'}.`} body="A few thoughtful steps today add up to a very good week." action={<Button onClick={() => { setEdit(undefined); setForm(true); }} data-testid="button-add-quest"><Plus className="h-4 w-4" /> Add a quest</Button>} /><div className="grid gap-5 lg:grid-cols-[1.35fr_.65fr]"><section className="space-y-5"><div className="rounded-3xl bg-[#302f48] p-5 text-[#fff7e8] shadow-route sm:p-7"><div className="flex items-start justify-between gap-4"><div><p className="font-mono-ui text-[10px] tracking-[.2em] text-[#aaa9ba] uppercase">Today’s trail</p><p className="mt-3 font-display text-4xl font-bold">{myDone}<span className="text-[#77768b]">/{mine.length}</span></p><p className="mt-1 text-sm text-[#bdbaca]">quests reached</p></div><div className="grid h-14 w-14 place-items-center rounded-2xl bg-[#f7ca56] text-[#302f48]"><Flag className="h-6 w-6" /></div></div><div className="mt-6 h-2 overflow-hidden rounded-full bg-[#ffffff15]"><div className="h-full rounded-full bg-[#f7ca56] transition-all duration-700" style={{ width: `${mine.length ? (myDone / mine.length) * 100 : 0}%` }} /></div><div className="mt-3 flex justify-between text-xs text-[#aaa9ba]"><span>{mine.length - myDone} still ahead</span><span>{myDone ? 'Nice pace.' : 'Your first step is waiting.'}</span></div></div><div className="flex items-center justify-between"><h2 className="font-display text-2xl font-bold">Your quests</h2><span className="font-mono-ui text-xs text-muted-foreground">{mine.length} pinned</span></div>{mine.length === 0 ? <EmptyState icon={Target} title="The map is blank" body="Pin a quest that would make today feel a little more yours." action={<Button onClick={() => setForm(true)} data-testid="button-empty-add-quest"><Plus className="h-4 w-4" /> Pin a quest</Button>} /> : <div className="space-y-3">{nextUp.map((quest) => <QuestRow key={quest.id} quest={quest} owner={me} onComplete={() => finish(quest)} onDelete={() => del(quest)} onEdit={() => { setEdit(quest); setForm(true); }} />)}{mine.filter((q) => q.status === 'completed').map((quest) => <QuestRow key={quest.id} quest={quest} owner={me} onComplete={() => finish(quest)} onDelete={() => del(quest)} onEdit={() => { setEdit(quest); setForm(true); }} />)}</div>}</section><aside className="space-y-5"><div className="rounded-3xl border border-[#dfd3c1] bg-[#fffaf1] p-5 sm:p-6"><div className="flex items-center justify-between"><h2 className="font-display text-xl font-bold">Your partner</h2><Link href="/together" data-testid="link-see-partner" className="text-xs font-bold text-[#9a7a2b] hover:underline">See all</Link></div>{other ? <><div className="mt-5 flex items-center gap-3"><Avatar player={other} size="lg" /><div><p data-testid="text-partner-name" className="font-bold">{other.name}</p><p className="mt-1 text-xs text-muted-foreground">{state.quests.filter((q) => q.ownerId === other.id && q.status === 'completed').length} quests reached this week</p></div></div><div className="mt-5 rounded-xl bg-[#f0e8da] p-3 text-sm text-[#5f5a69]"><MessageCircle className="mb-2 h-4 w-4 text-[#668f7c]" /> Their latest step is on the map. Send a little wind at their back.</div><Link href="/together" data-testid="link-encourage-partner" className="mt-4 flex items-center justify-center gap-2 rounded-xl border border-[#d9cfbd] px-3 py-2.5 text-sm font-bold hover:bg-[#eee2d2]"><MessageCircle className="h-4 w-4" /> Send encouragement</Link></> : <div className="py-6 text-sm text-muted-foreground">Your partner has not joined yet. Share the room code when you are ready.</div>}</div><div className="texture-grid rounded-3xl border border-[#dfd3c1] bg-[#eee4d3] p-5"><p className="font-mono-ui text-[10px] tracking-[.2em] text-[#9a7a2b] uppercase">Road note</p><p className="mt-3 font-display text-xl font-bold leading-tight">Small is still a direction.</p><p className="mt-2 text-sm leading-6 text-muted-foreground">The road rewards showing up, not racing ahead.</p></div></aside></div>{form && <QuestForm state={state} editQuest={edit} onClose={() => setForm(false)} />}</>;
}

function MapPage({ state }: { state: GameState }) {
  const total = state.quests.length; const done = state.quests.filter((q) => q.status === 'completed').length; const level = state.currentLevel; const milestones = [{ n: 1, title: 'Leave the house', sub: 'Your first shared step', reached: level >= 1 }, { n: 2, title: 'Find your rhythm', sub: 'Reach 10 quests together', reached: level >= 2 }, { n: 3, title: 'Take the scenic route', sub: 'Keep a 7 day streak', reached: level >= 3 }, { n: 4, title: 'The good stuff', sub: 'A month of showing up', reached: level >= 4 }]; return <><PageHeader eyebrow="The long way home" title="Journey map" body="Every finished quest moves your shared marker a little farther into the story." /><div className="grid gap-5 lg:grid-cols-[1.1fr_.9fr]"><section className="texture-grid relative overflow-hidden rounded-3xl border border-[#dfd3c1] bg-[#eee4d3] p-6 sm:p-9"><div className="relative z-[1] flex items-start justify-between"><div><p className="font-mono-ui text-[10px] tracking-[.2em] text-[#9a7a2b] uppercase">Current chapter</p><h2 className="mt-2 font-display text-3xl font-bold">Chapter {level}</h2><p className="mt-2 max-w-xs text-sm leading-6 text-muted-foreground">The roadside is getting warmer. Keep going.</p></div><div className="grid h-14 w-14 place-items-center rounded-2xl bg-[#302f48] text-[#f7ca56]"><Mountain className="h-7 w-7" /></div></div><div className="relative z-[1] mt-12 flex items-center gap-3"><div className="h-5 w-5 rounded-full bg-[#579477] ring-8 ring-[#579477]/15" /><div className="h-1 flex-1 rounded-full bg-[#cfc1ab]"><div className="h-full rounded-full bg-[#579477]" style={{ width: `${total ? Math.min(100, (done / Math.max(total, 1)) * 100) : 0}%` }} /></div><div className="h-5 w-5 rounded-full border-2 border-[#b5a58b] bg-[#eee4d3]" /></div><div className="relative z-[1] mt-4 flex justify-between text-xs font-bold text-muted-foreground"><span data-testid="text-map-progress">{done} steps reached</span><span>Next overlook</span></div><div className="absolute -bottom-8 left-[35%] h-28 w-28 rounded-full bg-[#f7ca56]/40 blur-2xl" /></section><section className="rounded-3xl border border-[#dfd3c1] bg-[#fffaf1] p-6 sm:p-8"><div className="flex items-center justify-between"><h2 className="font-display text-2xl font-bold">Milestones</h2><span className="font-mono-ui text-xs text-muted-foreground">{milestones.filter((m) => m.reached).length}/{milestones.length}</span></div><div className="mt-6 space-y-1">{milestones.map((m, index) => <div key={m.n} className="flex gap-4"><div className="flex flex-col items-center"><div data-testid={`status-milestone-${m.n}`} className={`grid h-9 w-9 place-items-center rounded-full ${m.reached ? 'bg-[#579477] text-white' : 'border-2 border-[#d9cfbd] text-[#a8a092]'}`}>{m.reached ? <Check className="h-4 w-4" /> : <span className="font-mono-ui text-xs">{String(m.n).padStart(2, '0')}</span>}</div>{index < milestones.length - 1 && <div className={`my-1 h-9 w-px ${m.reached ? 'bg-[#a7c7b5]' : 'bg-[#e1d8ca]'}`} />}</div><div className="pb-5"><p className={`font-bold ${m.reached ? '' : 'text-muted-foreground'}`}>{m.title}</p><p className="mt-1 text-xs text-muted-foreground">{m.sub}</p></div></div>)}</div></section></div></>;
}

function CalendarPage({ state }: { state: GameState }) {
  const [month, setMonth] = useState(new Date()); const [selected, setSelected] = useState(today); const first = new Date(month.getFullYear(), month.getMonth(), 1); const start = (first.getDay() + 6) % 7; const days = new Date(month.getFullYear(), month.getMonth() + 1, 0).getDate(); const cells = Array.from({ length: Math.ceil((start + days) / 7) * 7 }, (_, i) => i >= start && i < start + days ? i - start + 1 : null); const byDate = (day: number) => state.quests.filter((q) => q.dueDate === `${month.getFullYear()}-${String(month.getMonth() + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`); return <><PageHeader eyebrow="Plan the good kind of busy" title="Calendar" body="A bird’s-eye view of both trails. Leave room for the unplanned bits too." /><div className="grid gap-5 lg:grid-cols-[1fr_300px]"><section className="rounded-3xl border border-[#dfd3c1] bg-[#fffaf1] p-4 sm:p-7"><div className="mb-6 flex items-center justify-between"><div><p className="font-mono-ui text-xs text-muted-foreground">{state.weekLabel}</p><h2 data-testid="text-calendar-month" className="font-display text-2xl font-bold">{month.toLocaleDateString(undefined, { month: 'long', year: 'numeric' })}</h2></div><div className="flex gap-1"><button onClick={() => setMonth(new Date(month.getFullYear(), month.getMonth() - 1, 1))} data-testid="button-calendar-prev" className="rounded-lg border border-[#d9cfbd] p-2 hover:bg-[#eee2d2]">←</button><button onClick={() => setMonth(new Date(month.getFullYear(), month.getMonth() + 1, 1))} data-testid="button-calendar-next" className="rounded-lg border border-[#d9cfbd] p-2 hover:bg-[#eee2d2]">→</button></div></div><div className="grid grid-cols-7 text-center text-[10px] font-extrabold tracking-wide text-muted-foreground uppercase">{['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'].map((d) => <div key={d} className="pb-3">{d}</div>)}</div><div className="grid grid-cols-7 gap-1">{cells.map((day, i) => { const quests = day ? byDate(day) : []; const date = day ? `${month.getFullYear()}-${String(month.getMonth() + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}` : ''; return <button key={i} onClick={() => date && setSelected(date)} disabled={!day} data-testid={day ? `button-calendar-day-${day}` : `calendar-empty-${i}`} className={`min-h-20 rounded-xl p-2 text-left transition ${!day ? 'cursor-default' : selected === date ? 'bg-[#302f48] text-[#fff7e8]' : 'hover:bg-[#eee2d2]'}`}><span className={`font-mono-ui text-xs ${date === today ? 'grid h-6 w-6 place-items-center rounded-full bg-[#f7ca56] text-[#302f48]' : ''}`}>{day}</span><div className="mt-2 space-y-1">{quests.slice(0, 2).map((q) => <span key={q.id} className={`block truncate rounded px-1 py-0.5 text-[9px] font-bold ${q.status === 'completed' ? 'bg-[#b9d4c1] text-[#315f4d] line-through' : 'bg-[#e8d7ab] text-[#745d25]'}`}>{q.title}</span>)}</div></button>; })}</div></section><aside className="rounded-3xl border border-[#dfd3c1] bg-[#fffaf1] p-6"><p className="font-mono-ui text-[10px] tracking-[.2em] text-[#9a7a2b] uppercase">{selected === today ? 'Today' : new Date(`${selected}T12:00`).toLocaleDateString(undefined, { month: 'short', day: 'numeric' })}</p><h2 className="mt-2 font-display text-2xl font-bold">{state.quests.filter((q) => q.dueDate === selected).length} quests</h2><div className="mt-5 space-y-3">{state.quests.filter((q) => q.dueDate === selected).map((q) => <div key={q.id} data-testid={`calendar-quest-${q.id}`} className="border-l-2 border-[#f7ca56] pl-3"><p className="text-sm font-bold">{q.title}</p><p className="mt-1 text-xs text-muted-foreground">{q.status === 'completed' ? 'Reached' : `+${q.coinValue} coins when done`}</p></div>)}{state.quests.filter((q) => q.dueDate === selected).length === 0 && <p className="text-sm leading-6 text-muted-foreground">A clear patch of road. Perfect for a spontaneous turn.</p>}</div></aside></div></>;
}

function RewardsPage({ state }: { state: GameState }) {
  const [form, setForm] = useState(false); const [title, setTitle] = useState(''); const [description, setDescription] = useState(''); const [cost, setCost] = useState('20'); const meId = localStorage.getItem('quest-road-player') ?? state.players[0]?.id ?? ''; const me = state.players.find((p) => p.id === meId) ?? state.players[0]; const create = useCreateReward(); const redeem = useRedeemReward(); const qc = useQueryClient(); const active = state.rewards.filter((r) => r.active); const submit = (e: FormEvent) => { e.preventDefault(); if (!title.trim()) return; create.mutate({ roomId: state.room.id, data: { title: title.trim(), description: description.trim(), cost: Number(cost), createdBy: meId } }, { onSuccess: () => { setForm(false); setTitle(''); setDescription(''); qc.invalidateQueries({ queryKey: getGetGameStateQueryKey(state.room.id) }); } }); };
  return <><PageHeader eyebrow="Shared reward shop" title="Choose your next yes." body="Spend the coins you earn on small, very real reasons to look forward." action={<Button onClick={() => setForm(true)} data-testid="button-add-reward"><Plus className="h-4 w-4" /> Add a reward</Button>} /><div className="mb-6 flex items-center justify-between rounded-2xl border border-[#dfd3c1] bg-[#eee4d3] p-4"><div className="flex items-center gap-3"><div className="grid h-10 w-10 place-items-center rounded-xl bg-[#f7ca56] text-[#302f48]"><Gem className="h-5 w-5" /></div><div><p className="text-xs font-bold text-muted-foreground">Your balance</p><p data-testid="text-reward-balance" className="font-mono-ui text-xl font-medium">{me?.coins ?? 0} coins</p></div></div><p className="hidden text-right text-xs text-muted-foreground sm:block">Earn more by reaching quests<br />on your own trail.</p></div><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">{active.map((reward) => <RewardCard key={reward.id} reward={reward} me={me} onRedeem={() => redeem.mutate({ roomId: state.room.id, rewardId: reward.id, data: { playerId: meId } }, { onSuccess: () => qc.invalidateQueries({ queryKey: getGetGameStateQueryKey(state.room.id) }) })} pending={redeem.isPending} />)}</div>{active.length === 0 && <EmptyState icon={Trophy} title="The shop is waiting" body="Add the first reward you both want to work toward." action={<Button onClick={() => setForm(true)} data-testid="button-empty-add-reward"><Plus className="h-4 w-4" /> Add reward</Button>} />}{state.transactions.length > 0 && <section className="mt-10"><h2 className="mb-4 font-display text-2xl font-bold">Coin trail</h2><div className="divide-y divide-[#e1d8ca] rounded-2xl border border-[#dfd3c1] bg-[#fffaf1]">{state.transactions.slice(0, 8).map((tx) => <div key={tx.id} data-testid={`row-transaction-${tx.id}`} className="flex items-center justify-between px-4 py-3 text-sm"><div><p className="font-bold">{tx.label}</p><p className="mt-0.5 text-xs text-muted-foreground">{new Date(tx.createdAt).toLocaleDateString()}</p></div><span className={`font-mono-ui font-medium ${tx.amount >= 0 ? 'text-[#4c8569]' : 'text-[#a14f48]'}`}>{tx.amount >= 0 ? '+' : ''}{tx.amount}</span></div>)}</div></section>}{form && <div className="fixed inset-0 z-50 grid place-items-center bg-[#24243b]/55 p-4"><div className="w-full max-w-md rounded-3xl bg-[#fffaf1] p-7"><div className="mb-5 flex justify-between"><div><p className="font-mono-ui text-[10px] tracking-[.2em] text-[#9a7a2b] uppercase">New reward</p><h2 className="font-display text-2xl font-bold">Make it worth the wait</h2></div><button onClick={() => setForm(false)} data-testid="button-close-reward-form"><X /></button></div><form onSubmit={submit} className="space-y-4"><label className="block text-sm font-bold">Reward name<input value={title} onChange={(e) => setTitle(e.target.value)} placeholder="Takeaway and a sunset walk" data-testid="input-reward-title" className="mt-2 w-full rounded-xl border border-[#d9cfbd] bg-[#fffdf8] px-4 py-3 outline-none focus:border-[#c4962b]" /></label><label className="block text-sm font-bold">Description<textarea value={description} onChange={(e) => setDescription(e.target.value)} rows={2} placeholder="The good kind of evening." data-testid="input-reward-description" className="mt-2 w-full resize-none rounded-xl border border-[#d9cfbd] bg-[#fffdf8] px-4 py-3 outline-none focus:border-[#c4962b]" /></label><label className="block text-sm font-bold">Coin cost<input type="number" min="1" value={cost} onChange={(e) => setCost(e.target.value)} data-testid="input-reward-cost" className="mt-2 w-full rounded-xl border border-[#d9cfbd] bg-[#fffdf8] px-4 py-3 outline-none focus:border-[#c4962b]" /></label><Button type="submit" disabled={create.isPending} data-testid="button-save-reward" className="w-full">{create.isPending ? <Loader2 className="animate-spin" /> : 'Add to the shop'}</Button></form></div></div>}</>;
}

function RewardCard({ reward, me, onRedeem, pending }: { reward: Reward; me?: Player; onRedeem: () => void; pending: boolean }) {
  const canAfford = (me?.coins ?? 0) >= reward.cost; return <article data-testid={`card-reward-${reward.id}`} className="flex flex-col rounded-3xl border border-[#dfd3c1] bg-[#fffaf1] p-5 transition hover:-translate-y-1 hover:shadow-route"><div className="grid h-12 w-12 place-items-center rounded-2xl bg-[#302f48] text-[#f7ca56]"><Star className="h-6 w-6" /></div><h3 className="mt-5 font-display text-xl font-bold">{reward.title}</h3><p className="mt-2 min-h-10 text-sm leading-5 text-muted-foreground">{reward.description ?? 'A little something to look forward to.'}</p><div className="mt-6 flex items-center justify-between border-t border-[#e8dfd1] pt-4"><span className="flex items-center gap-1.5 font-mono-ui text-sm text-[#ad7d1e]"><Gem className="h-4 w-4" /> {reward.cost}</span><Button onClick={onRedeem} disabled={!canAfford || pending} data-testid={`button-redeem-reward-${reward.id}`} className="px-3 py-2 text-xs">{canAfford ? 'Redeem' : 'Keep exploring'}</Button></div></article>;
}

function QuestRowV2({ quest, owner, label, onComplete, onDelete, onEdit }: { quest: Quest; owner?: Player; label?: Label; onComplete: () => void; onDelete: () => void; onEdit: () => void }) {
  const complete = quest.status === 'completed';
  const accent = label?.color ?? '#c4962b';
  return <article data-testid={`card-quest-${quest.id}`} className={`group rounded-2xl border border-[#dfd3c1] border-l-4 bg-[#fffaf1] p-4 transition-all hover:-translate-y-0.5 hover:shadow-route ${complete ? 'bg-[#f3f8f3]' : ''}`} style={{ borderLeftColor: accent }}><div className="flex items-start gap-3"><button onClick={onComplete} aria-label={complete ? 'Reopen quest' : 'Complete quest'} data-testid={`button-complete-quest-${quest.id}`} className={`mt-0.5 grid h-6 w-6 shrink-0 place-items-center rounded-full border-2 transition ${complete ? 'border-[#579477] bg-[#579477] text-white' : 'border-[#b7aa95] hover:border-[#c4962b] hover:bg-[#f7ca56]'}`}>{complete && <Check className="h-3.5 w-3.5" />}</button><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><h3 className={`font-bold ${complete ? 'text-[#74897b] line-through' : ''}`}>{quest.title}</h3><span className={`rounded-md px-2 py-0.5 text-[10px] font-extrabold uppercase tracking-wide ${quest.priority === 'major' ? 'bg-[#f3d5d0] text-[#a14f48]' : quest.priority === 'medium' ? 'bg-[#eee2c6] text-[#93752c]' : 'bg-[#dce9e2] text-[#4d8067]'}`}>{quest.priority}</span>{label && <span className="rounded-md px-2 py-0.5 text-[10px] font-extrabold" style={{ backgroundColor: `${label.color}22`, color: label.color }}>{label.name}</span>}</div>{quest.notes && <p className="mt-1 line-clamp-2 text-xs leading-5 text-muted-foreground">{quest.notes}</p>}<div className="mt-3 flex flex-wrap items-center gap-3 text-[11px] font-semibold text-muted-foreground"><span className="flex items-center gap-1"><CalendarDays className="h-3.5 w-3.5" /> {quest.dueDate ? quest.dueDate === today ? 'Today' : formatDate(quest.dueDate) : 'Someday'}</span><span className="flex items-center gap-1 text-[#ad7d1e]"><Gem className="h-3.5 w-3.5" /> +{quest.coinValue} coins</span><span className="flex items-center gap-1 text-[#6685a0]"><Star className="h-3.5 w-3.5" /> +{quest.xpValue} XP</span>{owner && <span className="ml-auto flex items-center gap-1.5"><Avatar player={owner} size="sm" /> {owner.name}</span>}</div></div><div className="flex gap-1 opacity-0 transition group-hover:opacity-100"><button onClick={onEdit} data-testid={`button-edit-quest-${quest.id}`} className="rounded-lg p-2 text-muted-foreground hover:bg-[#eee2d2] hover:text-foreground"><Pencil className="h-4 w-4" /></button><button onClick={onDelete} data-testid={`button-delete-quest-${quest.id}`} className="rounded-lg p-2 text-muted-foreground hover:bg-[#f3d5d0] hover:text-[#a14f48]"><X className="h-4 w-4" /></button></div></div></article>;
}

function LabelManager({ state, onClose }: { state: GameState; onClose: () => void }) {
  const meId = localStorage.getItem('quest-road-player') ?? state.players[0]?.id ?? '';
  const labels = state.labels.filter((label) => label.ownerId === meId);
  const [name, setName] = useState('');
  const [color, setColor] = useState(labelColors[0]);
  const [editing, setEditing] = useState<string | null>(null);
  const create = useCreateLabel();
  const update = useUpdateLabel();
  const remove = useDeleteLabel();
  const qc = useQueryClient();
  const refresh = () => qc.invalidateQueries({ queryKey: getGetGameStateQueryKey(state.room.id) });
  const save = (event: FormEvent) => {
    event.preventDefault();
    if (!name.trim()) return;
    if (editing) update.mutate({ roomId: state.room.id, labelId: editing, data: { ownerId: meId, name: name.trim(), color } }, { onSuccess: () => { setEditing(null); setName(''); refresh(); } });
    else create.mutate({ roomId: state.room.id, data: { ownerId: meId, name: name.trim(), color } }, { onSuccess: () => { setName(''); refresh(); } });
  };
  const beginEdit = (label: Label) => { setEditing(label.id); setName(label.name); setColor(label.color); };
  const cancel = () => { setEditing(null); setName(''); setColor(labelColors[0]); };
  return <div className="fixed inset-0 z-[60] grid place-items-center bg-[#24243b]/55 p-4" role="dialog" aria-modal="true"><div className="w-full max-w-md rounded-3xl bg-[#fffaf1] p-6 shadow-[0_24px_70px_rgba(20,20,40,.25)] sm:p-8"><div className="mb-5 flex items-start justify-between"><div><p className="font-mono-ui text-[10px] tracking-[.2em] text-[#9a7a2b] uppercase">Personal labels</p><h2 className="mt-1 font-display text-2xl font-bold">Name your kinds of work</h2></div><button onClick={onClose} data-testid="button-close-labels"><X /></button></div><div className="mb-5 space-y-2">{labels.map((label) => <div key={label.id} className="flex items-center gap-3 rounded-xl border border-[#e5dacb] p-2.5"><span className="h-3 w-3 rounded-full" style={{ backgroundColor: label.color }} /><span className="flex-1 text-sm font-bold">{label.name}</span><button onClick={() => beginEdit(label)} className="rounded-lg p-2 text-muted-foreground hover:bg-[#eee2d2]" aria-label={`Edit ${label.name}`}><Pencil className="h-4 w-4" /></button><button onClick={() => { if (window.confirm(`Delete ${label.name}?`)) remove.mutate({ roomId: state.room.id, labelId: label.id, data: { ownerId: meId } }, { onSuccess: refresh }); }} className="rounded-lg p-2 text-muted-foreground hover:bg-[#f3d5d0] hover:text-[#a14f48]" aria-label={`Delete ${label.name}`}><X className="h-4 w-4" /></button></div>)}{labels.length === 0 && <p className="rounded-xl bg-[#f0e8da] p-3 text-sm text-muted-foreground">No labels yet. Add one for a trail you return to often.</p>}</div><form onSubmit={save} className="space-y-3"><input value={name} onChange={(e) => setName(e.target.value)} placeholder="e.g. Job search" data-testid="input-label-name" className="w-full rounded-xl border border-[#d9cfbd] bg-[#fffdf8] px-4 py-3 text-sm outline-none focus:border-[#c4962b]" /><div className="flex items-center gap-2">{labelColors.map((option) => <button type="button" key={option} onClick={() => setColor(option)} aria-label={`Choose ${option}`} className={`h-7 w-7 rounded-full border-2 ${color === option ? 'border-[#302f48] ring-2 ring-[#f7ca56]' : 'border-transparent'}`} style={{ backgroundColor: option }} />)}<input type="color" value={color} onChange={(e) => setColor(e.target.value)} aria-label="Custom label colour" className="h-8 w-8 rounded-full border-0 bg-transparent p-0" /></div><div className="flex gap-2"><Button type="submit" disabled={!name.trim() || create.isPending || update.isPending} className="flex-1">{editing ? 'Save label' : 'Create label'}</Button>{editing && <Button type="button" variant="ghost" onClick={cancel}>Cancel</Button>}</div></form></div></div>;
}

function QuestFormV2({ state, editQuest, onClose }: { state: GameState; editQuest?: Quest; onClose: () => void }) {
  const roomId = state.room.id;
  const meId = localStorage.getItem('quest-road-player') ?? state.players[0]?.id ?? '';
  const [title, setTitle] = useState(editQuest?.title ?? '');
  const [notes, setNotes] = useState(editQuest?.notes ?? '');
  const [scheduled, setScheduled] = useState(Boolean(editQuest?.dueDate ?? !editQuest));
  const [dueDate, setDueDate] = useState(editQuest?.dueDate ?? today);
  const [priority, setPriority] = useState<QuestPriority>(editQuest?.priority ?? 'small');
  const [labelId, setLabelId] = useState(editQuest?.labelId ?? '');
  const [labelsOpen, setLabelsOpen] = useState(false);
  const create = useCreateQuest();
  const update = useUpdateQuest();
  const qc = useQueryClient();
  const labels = state.labels.filter((label) => label.ownerId === meId);
  const save = (event: FormEvent) => {
    event.preventDefault();
    if (!title.trim()) return;
    const data = { ownerId: meId, title: title.trim(), notes: notes.trim(), dueDate: scheduled ? dueDate : null, labelId: labelId || null, priority };
    const done = () => { qc.invalidateQueries({ queryKey: getGetGameStateQueryKey(roomId) }); onClose(); };
    if (editQuest) update.mutate({ roomId, questId: editQuest.id, data }, { onSuccess: done });
    else create.mutate({ roomId, data }, { onSuccess: done });
  };
  const pending = create.isPending || update.isPending;
  return <div className="fixed inset-0 z-50 grid place-items-center overflow-y-auto bg-[#24243b]/55 p-4" role="dialog" aria-modal="true"><div className="my-6 w-full max-w-lg rounded-3xl bg-[#fffaf1] p-6 shadow-[0_24px_70px_rgba(20,20,40,.25)] sm:p-8"><div className="mb-6 flex items-start justify-between"><div><p className="font-mono-ui text-[10px] tracking-[.2em] text-[#9a7a2b] uppercase">{editQuest ? 'Edit quest' : 'New quest'}</p><h2 className="mt-1 font-display text-2xl font-bold">{editQuest ? 'Tune the route' : 'Add a small adventure'}</h2></div><button onClick={onClose} data-testid="button-close-quest-form"><X className="h-5 w-5" /></button></div><form onSubmit={save} className="space-y-4"><label className="block text-sm font-bold">Quest title<input autoFocus value={title} onChange={(e) => setTitle(e.target.value)} placeholder="Leave work on time" data-testid="input-quest-title" className="mt-2 w-full rounded-xl border border-[#d9cfbd] bg-[#fffdf8] px-4 py-3 outline-none focus:border-[#c4962b]" /></label><label className="block text-sm font-bold">A note <span className="font-normal text-muted-foreground">(optional)</span><textarea value={notes} onChange={(e) => setNotes(e.target.value)} rows={3} placeholder="What would make this feel done?" data-testid="input-quest-notes" className="mt-2 w-full resize-none rounded-xl border border-[#d9cfbd] bg-[#fffdf8] px-4 py-3 text-sm outline-none focus:border-[#c4962b]" /></label><div className="grid gap-4 sm:grid-cols-2"><div><span className="block text-sm font-bold">Timing</span><div className="mt-2 flex rounded-xl bg-[#eee5d5] p-1 text-xs font-bold"><button type="button" onClick={() => setScheduled(true)} className={`flex-1 rounded-lg px-2 py-2 ${scheduled ? 'bg-[#302f48] text-[#fff7e8]' : 'text-[#797388]'}`}>Scheduled</button><button type="button" onClick={() => setScheduled(false)} className={`flex-1 rounded-lg px-2 py-2 ${!scheduled ? 'bg-[#302f48] text-[#fff7e8]' : 'text-[#797388]'}`}>Someday</button></div>{scheduled && <input type="date" value={dueDate} onChange={(e) => setDueDate(e.target.value)} data-testid="input-quest-due-date" className="mt-2 w-full rounded-xl border border-[#d9cfbd] bg-[#fffdf8] px-3 py-2.5 text-sm outline-none focus:border-[#c4962b]" />}</div><label className="block text-sm font-bold">Trail weight<select value={priority} onChange={(e) => setPriority(e.target.value as QuestPriority)} data-testid="select-quest-priority" className="mt-2 w-full rounded-xl border border-[#d9cfbd] bg-[#fffdf8] px-3 py-2.5 text-sm outline-none focus:border-[#c4962b]"><option value="small">Small · 10 coins</option><option value="medium">Medium · 20 coins</option><option value="major">Major · 30 coins</option></select></label></div><div><div className="flex items-center justify-between"><span className="text-sm font-bold">Label <span className="font-normal text-muted-foreground">(optional)</span></span><button type="button" onClick={() => setLabelsOpen(true)} className="text-xs font-bold text-[#9a7a2b] hover:underline"><Palette className="mr-1 inline h-3.5 w-3.5" />Manage labels</button></div><select value={labelId} onChange={(e) => setLabelId(e.target.value)} data-testid="select-quest-label" className="mt-2 w-full rounded-xl border border-[#d9cfbd] bg-[#fffdf8] px-3 py-2.5 text-sm outline-none focus:border-[#c4962b]"><option value="">No label</option>{labels.map((label) => <option value={label.id} key={label.id}>{label.name}</option>)}</select></div><Button type="submit" disabled={pending || !title.trim()} data-testid="button-save-quest" className="mt-2 w-full">{pending ? <Loader2 className="h-4 w-4 animate-spin" /> : editQuest ? 'Save changes' : 'Pin this quest'}</Button></form>{labelsOpen && <LabelManager state={state} onClose={() => setLabelsOpen(false)} />}</div></div>;
}

function TodayPageV2({ state }: { state: GameState }) {
  const [form, setForm] = useState(false);
  const [edit, setEdit] = useState<Quest>();
  const qc = useQueryClient();
  const complete = useSetQuestCompleted();
  const remove = useDeleteQuest();
  const meId = localStorage.getItem('quest-road-player') ?? state.players[0]?.id ?? '';
  const me = state.players.find((player) => player.id === meId) ?? state.players[0];
  const mine = state.quests.filter((quest) => quest.ownerId === me?.id);
  const scheduled = mine.filter((quest) => quest.dueDate);
  const someday = mine.filter((quest) => !quest.dueDate);
  const sorted = [...scheduled].sort((a, b) => (a.dueDate ?? '').localeCompare(b.dueDate ?? ''));
  const finish = (quest: Quest) => complete.mutate({ roomId: state.room.id, questId: quest.id, data: { ownerId: quest.ownerId, completed: quest.status !== 'completed' } }, { onSuccess: () => qc.invalidateQueries({ queryKey: getGetGameStateQueryKey(state.room.id) }) });
  const del = (quest: Quest) => { if (window.confirm('Remove this quest from the road?')) remove.mutate({ roomId: state.room.id, questId: quest.id, data: { ownerId: quest.ownerId } }, { onSuccess: () => qc.invalidateQueries({ queryKey: getGetGameStateQueryKey(state.room.id) }) }); };
  const row = (quest: Quest) => <QuestRowV2 key={quest.id} quest={quest} owner={me} label={state.labels.find((label) => label.id === quest.labelId)} onComplete={() => finish(quest)} onDelete={() => del(quest)} onEdit={() => { setEdit(quest); setForm(true); }} />;
  return <><PageHeader eyebrow={state.weekLabel} title={`Good morning, ${me?.name ?? 'wayfarer'}.`} body="A few thoughtful steps today add up to a very good week." action={<Button onClick={() => { setEdit(undefined); setForm(true); }} data-testid="button-add-quest"><Plus className="h-4 w-4" /> Add a quest</Button>} /><div className="grid gap-5 lg:grid-cols-[1.35fr_.65fr]"><section className="space-y-6"><div className="rounded-3xl bg-[#302f48] p-5 text-[#fff7e8] shadow-route sm:p-7"><div className="flex items-start justify-between gap-4"><div><p className="font-mono-ui text-[10px] tracking-[.2em] text-[#aaa9ba] uppercase">Scheduled trail</p><p className="mt-3 font-display text-4xl font-bold">{scheduled.filter((quest) => quest.status === 'completed').length}<span className="text-[#77768b]">/{scheduled.length}</span></p><p className="mt-1 text-sm text-[#bdbaca]">planned quests reached</p></div><div className="grid h-14 w-14 place-items-center rounded-2xl bg-[#f7ca56] text-[#302f48]"><Flag className="h-6 w-6" /></div></div><div className="mt-6 h-2 overflow-hidden rounded-full bg-[#ffffff15]"><div className="h-full rounded-full bg-[#f7ca56]" style={{ width: `${scheduled.length ? scheduled.filter((quest) => quest.status === 'completed').length / scheduled.length * 100 : 0}%` }} /></div><div className="mt-3 flex justify-between text-xs text-[#aaa9ba]"><span>{scheduled.filter((quest) => quest.status !== 'completed').length} still ahead</span><span>Someday quests stay off the clock.</span></div></div><div className="flex items-center justify-between"><h2 className="font-display text-2xl font-bold">Your scheduled quests</h2><span className="font-mono-ui text-xs text-muted-foreground">{scheduled.length} planned</span></div>{scheduled.length === 0 ? <EmptyState icon={Target} title="The map is blank" body="Pin a scheduled quest or keep something for someday." action={<Button onClick={() => setForm(true)}><Plus className="h-4 w-4" /> Pin a quest</Button>} /> : <div className="space-y-3">{sorted.map(row)}</div>}<div className="rounded-3xl border border-[#dfd3c1] bg-[#fffaf1] p-5 sm:p-6"><div className="flex items-center justify-between"><div><p className="font-mono-ui text-[10px] tracking-[.2em] text-[#9a7a2b] uppercase">No deadline</p><h2 className="mt-1 font-display text-2xl font-bold">Someday</h2></div><span className="rounded-full bg-[#eee2d2] px-3 py-1 text-xs font-bold">{someday.length}</span></div><p className="mt-2 text-sm leading-6 text-muted-foreground">Good ideas with no pressure attached. They do not affect weekly progress.</p>{someday.length > 0 && <div className="mt-4 space-y-3">{someday.map(row)}</div>}{someday.length === 0 && <p className="mt-4 rounded-xl bg-[#f0e8da] p-3 text-sm text-muted-foreground">Nothing waiting in the wings.</p>}</div></section><aside className="space-y-5"><div className="rounded-3xl border border-[#dfd3c1] bg-[#fffaf1] p-5 sm:p-6"><div className="flex items-center justify-between"><h2 className="font-display text-xl font-bold">Your partner</h2><Link href="/together" className="text-xs font-bold text-[#9a7a2b] hover:underline">See all</Link></div>{state.players.find((player) => player.id !== me?.id) ? <div className="mt-5 flex items-center gap-3"><Avatar player={state.players.find((player) => player.id !== me?.id)} size="lg" /><div><p className="font-bold">{state.players.find((player) => player.id !== me?.id)?.name}</p><p className="mt-1 text-xs text-muted-foreground">Their trail is moving alongside yours.</p></div></div> : <div className="py-6 text-sm text-muted-foreground">Your partner has not joined yet. Share the room link.</div>}</div><div className="texture-grid rounded-3xl border border-[#dfd3c1] bg-[#eee4d3] p-5"><p className="font-mono-ui text-[10px] tracking-[.2em] text-[#9a7a2b] uppercase">Road note</p><p className="mt-3 font-display text-xl font-bold leading-tight">Small is still a direction.</p><p className="mt-2 text-sm leading-6 text-muted-foreground">The road rewards showing up, not racing ahead.</p></div></aside></div>{form && <QuestFormV2 state={state} editQuest={edit} onClose={() => setForm(false)} />}</>;
}

function MapPageV2({ state }: { state: GameState }) {
  const [selectedStart, setSelectedStart] = useState(weekStart);
  const starts = Array.from({ length: 12 }, (_, index) => addDays(weekStart, (index - 2) * 7));
  const currentIndex = 2;
  const selected = starts.includes(selectedStart) ? selectedStart : weekStart;
  const playerProgress = (playerId: string, start: string) => {
    const end = addDays(start, 6);
    const quests = state.quests.filter((quest) => quest.ownerId === playerId && quest.dueDate && quest.dueDate >= start && quest.dueDate <= end);
    const completed = quests.filter((quest) => quest.status === 'completed').length;
    return { quests, completed, planned: quests.length, progress: quests.length ? Math.round(completed / quests.length * 100) : 0, coins: state.transactions.filter((tx) => tx.playerId === playerId && tx.amount > 0 && tx.createdAt.slice(0, 10) >= start && tx.createdAt.slice(0, 10) <= end).reduce((total, tx) => total + tx.amount, 0) };
  };
  const selectedData = state.players.map((player) => ({ player, ...playerProgress(player.id, selected) }));
  return <><PageHeader eyebrow="The long way home" title="Journey map" body="The same road, two markers. Each weekly level is a stop, not a race." /><div className="grid gap-5 lg:grid-cols-[1.1fr_.9fr]"><section className="texture-grid relative overflow-hidden rounded-3xl border border-[#dfd3c1] bg-[#eee4d3] p-5 sm:p-8"><div className="relative z-[1] flex items-start justify-between"><div><p className="font-mono-ui text-[10px] tracking-[.2em] text-[#9a7a2b] uppercase">The weekly road</p><h2 className="mt-2 font-display text-3xl font-bold">Keep your own pace.</h2><p className="mt-2 max-w-sm text-sm leading-6 text-muted-foreground">Tap a stop to see what was planned, what was reached, and what is waiting ahead.</p></div><div className="grid h-14 w-14 place-items-center rounded-2xl bg-[#302f48] text-[#f7ca56]"><Mountain className="h-7 w-7" /></div></div><div className="relative mt-8 space-y-1 pb-4 before:absolute before:bottom-6 before:left-[27px] before:top-6 before:w-1 before:rounded-full before:bg-[#c8b89e] before:content-['']">{starts.map((start, index) => { const isCurrent = index === currentIndex; const isPast = index < currentIndex; const progress = state.players.map((player) => playerProgress(player.id, start)); return <div key={start}>{index === 5 && <div className="relative z-[1] flex items-center gap-4 py-3 pl-2"><div className="grid h-10 w-10 place-items-center rounded-full bg-[#f7ca56] text-[#302f48] shadow-[0_3px_0_#c4962b]"><Star className="h-5 w-5 fill-current" /></div><div><p className="font-mono-ui text-[10px] tracking-[.15em] text-[#9a7a2b] uppercase">Major milestone</p><p className="text-sm font-bold">A bigger view of the road</p></div></div>}<button onClick={() => setSelectedStart(start)} data-testid={`button-map-level-${index + 1}`} className={`relative z-[1] flex w-full items-center gap-4 rounded-2xl p-2 text-left transition hover:bg-[#fffaf1]/70 ${selected === start ? 'bg-[#fffaf1] shadow-sm' : ''}`}><div className={`grid h-12 w-12 shrink-0 place-items-center rounded-full border-4 ${isCurrent ? 'border-[#f7ca56] bg-[#302f48] text-[#f7ca56]' : isPast ? 'border-[#579477] bg-[#579477] text-white' : 'border-[#b7aa95] bg-[#eee4d3] text-[#7e7565]'}`}>{isCurrent ? <Compass className="h-5 w-5" /> : isPast ? <Check className="h-5 w-5" /> : <span className="font-mono-ui text-xs">{index + 1}</span>}</div><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><p className="font-bold">Level {index + 1}</p>{isCurrent && <span className="rounded-full bg-[#f7ca56] px-2 py-0.5 text-[10px] font-extrabold uppercase">Current</span>}{isPast && <span className="text-[10px] font-bold uppercase text-[#579477]">Past</span>}{!isPast && !isCurrent && <span className="text-[10px] font-bold uppercase text-muted-foreground">Future</span>}</div><p className="mt-0.5 text-xs text-muted-foreground">{weekRange(start)}</p><div className="mt-2 flex -space-x-1">{state.players.map((player, playerIndex) => <span key={player.id} className="relative grid h-6 w-6 place-items-center rounded-full border-2 border-[#eee4d3] text-[8px] font-extrabold text-white" style={{ backgroundColor: playerIndex ? '#6f9f8b' : '#a47c43', left: `${progress[playerIndex]?.progress ?? 0 / 8}px` }}>{initials(player.name).slice(0, 1)}</span>)}</div></div><ChevronRight className="h-4 w-4 text-[#a69b8b]" /></button></div>; })}</div></section><aside className="rounded-3xl border border-[#dfd3c1] bg-[#fffaf1] p-6 sm:p-8"><p className="font-mono-ui text-[10px] tracking-[.2em] text-[#9a7a2b] uppercase">Level {starts.indexOf(selected) + 1} · {selected === weekStart ? 'Current week' : selected < weekStart ? 'Past week' : 'Future week'}</p><h2 className="mt-2 font-display text-2xl font-bold">{weekRange(selected)}</h2>{selected === weekStart && <p className="mt-1 text-sm text-muted-foreground">{state.daysRemaining} days remaining</p>}<div className="mt-6 space-y-4">{selectedData.map(({ player, quests, completed, planned, progress, coins }) => <div key={player.id} className="rounded-2xl bg-[#f0e8da] p-4"><div className="flex items-center gap-3"><Avatar player={player} size="sm" /><div className="flex-1"><p className="text-sm font-bold">{player.name}</p><p className="text-xs text-muted-foreground">{completed} reached / {planned} planned</p></div><span className="font-mono-ui text-sm text-[#ad7d1e]">{coins} coins</span></div><div className="mt-3 h-2 overflow-hidden rounded-full bg-[#dfd3c1]"><div className="h-full rounded-full bg-[#579477]" style={{ width: `${progress}%` }} /></div><p className="mt-2 text-right text-xs font-bold text-muted-foreground">{progress}% progress</p></div>)}</div><p className="mt-6 text-xs leading-5 text-muted-foreground">Only scheduled quests shape weekly progress. Someday quests stay available without moving the level.</p></aside></div></>;
}

function RewardCardV2({ reward, me, onRedeem, onEdit, onDelete, pending }: { reward: Reward; me?: Player; onRedeem: () => void; onEdit: () => void; onDelete: () => void; pending: boolean }) {
  const canAfford = (me?.coins ?? 0) >= reward.cost;
  return <article data-testid={`card-reward-${reward.id}`} className="flex flex-col rounded-3xl border border-[#dfd3c1] bg-[#fffaf1] p-5 transition hover:-translate-y-1 hover:shadow-route"><div className="flex items-start justify-between"><div className="grid h-12 w-12 place-items-center rounded-2xl bg-[#302f48] text-[#f7ca56]"><Star className="h-6 w-6" /></div><div className="flex gap-1"><button onClick={onEdit} aria-label={`Edit ${reward.title}`} className="rounded-lg p-2 text-muted-foreground hover:bg-[#eee2d2]"><Pencil className="h-4 w-4" /></button><button onClick={onDelete} aria-label={`Delete ${reward.title}`} className="rounded-lg p-2 text-muted-foreground hover:bg-[#f3d5d0] hover:text-[#a14f48]"><X className="h-4 w-4" /></button></div></div><h3 className="mt-5 font-display text-xl font-bold">{reward.title}</h3><p className="mt-2 min-h-10 text-sm leading-5 text-muted-foreground">{reward.description ?? 'A little something to look forward to.'}</p><div className="mt-6 flex items-center justify-between border-t border-[#e8dfd1] pt-4"><span className="flex items-center gap-1.5 font-mono-ui text-sm text-[#ad7d1e]"><Gem className="h-4 w-4" /> {reward.cost}</span><Button onClick={onRedeem} disabled={!canAfford || pending} className="px-3 py-2 text-xs">{canAfford ? 'Redeem' : 'Keep exploring'}</Button></div></article>;
}

function RewardRequestCard({ request, me, players, onRespond }: { request: RewardRequest; me?: Player; players: Player[]; onRespond: (request: RewardRequest, action: 'accept' | 'counter' | 'decline', offer?: number) => void }) {
  const requester = players.find((player) => player.id === request.requesterId);
  const responder = players.find((player) => player.id === request.responderId);
  const mine = request.requesterId === me?.id;
  const waitingForMe = (request.status === 'awaiting_response' && request.responderId === me?.id) || (request.status === 'countered' && request.requesterId === me?.id);
  const status = request.status === 'awaiting_response' ? (mine ? 'Awaiting their response' : 'Your response needed') : request.status === 'countered' ? `Counteroffer: ${request.offer} coins` : request.status === 'accepted' ? 'Accepted' : 'Declined';
  return <article data-testid={`card-reward-request-${request.id}`} className="rounded-2xl border border-[#dfd3c1] bg-[#fffaf1] p-4"><div className="flex items-start justify-between gap-3"><div><p className="text-sm font-bold">{request.title}</p><p className="mt-1 text-xs text-muted-foreground">{requester?.name} offers {request.offer} coins to {responder?.name}</p></div><span className={`rounded-full px-2.5 py-1 text-[10px] font-extrabold uppercase ${request.status === 'accepted' ? 'bg-[#dce9e2] text-[#4d8067]' : request.status === 'declined' ? 'bg-[#f3d5d0] text-[#9f433e]' : 'bg-[#eee2c6] text-[#93752c]'}`}>{status}</span></div>{request.description && <p className="mt-3 text-sm leading-5 text-muted-foreground">{request.description}</p>}{waitingForMe && <div className="mt-4 flex flex-wrap gap-2">{request.status === 'awaiting_response' && <Button onClick={() => onRespond(request, 'accept')} className="px-3 py-2 text-xs">Accept {request.offer}</Button>}{request.status === 'countered' && <Button onClick={() => onRespond(request, 'accept')} className="px-3 py-2 text-xs">Accept {request.offer}</Button>}<Button variant="ghost" onClick={() => { const value = Number(window.prompt('New coin offer', String(request.offer))); if (value > 0) onRespond(request, 'counter', value); }} className="px-3 py-2 text-xs">Counter</Button><Button variant="danger" onClick={() => onRespond(request, 'decline')} className="px-3 py-2 text-xs">Decline</Button></div>}</article>;
}

function RewardsPageV2({ state }: { state: GameState }) {
  const [form, setForm] = useState(false);
  const [editing, setEditing] = useState<Reward | undefined>();
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [cost, setCost] = useState('20');
  const [requestForm, setRequestForm] = useState(false);
  const [requestTitle, setRequestTitle] = useState('');
  const [requestDescription, setRequestDescription] = useState('');
  const [requestOffer, setRequestOffer] = useState('80');
  const meId = localStorage.getItem('quest-road-player') ?? state.players[0]?.id ?? '';
  const me = state.players.find((player) => player.id === meId) ?? state.players[0];
  const create = useCreateReward();
  const update = useUpdateReward();
  const remove = useDeleteReward();
  const redeem = useRedeemReward();
  const createRequest = useCreateRewardRequest();
  const respond = useRespondToRewardRequest();
  const qc = useQueryClient();
  const active = state.rewards.filter((reward) => reward.active);
  const refresh = () => qc.invalidateQueries({ queryKey: getGetGameStateQueryKey(state.room.id) });
  const openCreate = () => { setEditing(undefined); setTitle(''); setDescription(''); setCost('20'); setForm(true); };
  const openEdit = (reward: Reward) => { setEditing(reward); setTitle(reward.title); setDescription(reward.description ?? ''); setCost(String(reward.cost)); setForm(true); };
  const save = (event: FormEvent) => {
    event.preventDefault();
    if (!title.trim() || Number(cost) < 1) return;
    if (editing) update.mutate({ roomId: state.room.id, rewardId: editing.id, data: { actorId: meId, title: title.trim(), description: description.trim() || null, cost: Number(cost) } }, { onSuccess: () => { setForm(false); refresh(); } });
    else create.mutate({ roomId: state.room.id, data: { title: title.trim(), description: description.trim(), cost: Number(cost), createdBy: meId } }, { onSuccess: () => { setForm(false); refresh(); } });
  };
  const sendRequest = (event: FormEvent) => { event.preventDefault(); if (!requestTitle.trim() || Number(requestOffer) < 1) return; createRequest.mutate({ roomId: state.room.id, data: { requesterId: meId, title: requestTitle.trim(), description: requestDescription.trim() || null, offer: Number(requestOffer) } }, { onSuccess: () => { setRequestForm(false); setRequestTitle(''); setRequestDescription(''); setRequestOffer('80'); refresh(); } }); };
  const respondTo = (request: RewardRequest, action: 'accept' | 'counter' | 'decline', offer?: number) => respond.mutate({ roomId: state.room.id, requestId: request.id, data: { actorId: meId, action, ...(offer ? { offer } : {}) } }, { onSuccess: refresh });
  return <><PageHeader eyebrow="Shared reward shop" title="Choose your next yes." body="Custom rewards and negotiated asks, both paid for with coins." action={<div className="flex flex-wrap gap-2"><Button variant="ghost" onClick={() => setRequestForm(true)} data-testid="button-request-reward"><Sparkles className="h-4 w-4" /> Request a reward</Button><Button onClick={openCreate} data-testid="button-add-reward"><Plus className="h-4 w-4" /> Add a reward</Button></div>} /><div className="mb-7 flex items-center justify-between rounded-2xl border border-[#dfd3c1] bg-[#eee4d3] p-4"><div className="flex items-center gap-3"><div className="grid h-10 w-10 place-items-center rounded-xl bg-[#f7ca56] text-[#302f48]"><Gem className="h-5 w-5" /></div><div><p className="text-xs font-bold text-muted-foreground">Your balance</p><p data-testid="text-reward-balance" className="font-mono-ui text-xl font-medium">{me?.coins ?? 0} coins</p></div></div><p className="hidden text-right text-xs text-muted-foreground sm:block">Rewards are yours to define.<br />No defaults, no guilt.</p></div><section><div className="mb-4 flex items-end justify-between"><div><p className="font-mono-ui text-[10px] tracking-[.2em] text-[#9a7a2b] uppercase">Room rewards</p><h2 className="font-display text-2xl font-bold">Your custom shop</h2></div><span className="text-xs text-muted-foreground">{active.length} available</span></div>{active.length ? <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">{active.map((reward) => <RewardCardV2 key={reward.id} reward={reward} me={me} onRedeem={() => redeem.mutate({ roomId: state.room.id, rewardId: reward.id, data: { playerId: meId } }, { onSuccess: refresh })} onEdit={() => openEdit(reward)} onDelete={() => { if (window.confirm(`Delete ${reward.title}?`)) remove.mutate({ roomId: state.room.id, rewardId: reward.id, data: { actorId: meId } }, { onSuccess: refresh }); }} pending={redeem.isPending} />)}</div> : <EmptyState icon={Trophy} title="The shop is waiting" body="Add the first reward you both want to work toward." action={<Button onClick={openCreate}><Plus className="h-4 w-4" /> Add reward</Button>} />}</section><section className="mt-10"><div className="mb-4 flex items-end justify-between"><div><p className="font-mono-ui text-[10px] tracking-[.2em] text-[#9a7a2b] uppercase">Negotiated asks</p><h2 className="font-display text-2xl font-bold">Reward requests</h2></div><span className="text-xs text-muted-foreground">{state.rewardRequests.length} total</span></div>{state.rewardRequests.length ? <div className="space-y-3">{state.rewardRequests.map((request) => <RewardRequestCard key={request.id} request={request} me={me} players={state.players} onRespond={respondTo} />)}</div> : <div className="rounded-2xl border border-dashed border-[#d7cbb8] bg-[#f8f1e5] p-5 text-sm text-muted-foreground">Ask your co-pilot for something specific, then agree on a fair offer.</div>}</section>{state.transactions.length > 0 && <section className="mt-10"><h2 className="mb-4 font-display text-2xl font-bold">Coin trail</h2><div className="divide-y divide-[#e1d8ca] rounded-2xl border border-[#dfd3c1] bg-[#fffaf1]">{state.transactions.slice(0, 8).map((tx) => <div key={tx.id} data-testid={`row-transaction-${tx.id}`} className="flex items-center justify-between px-4 py-3 text-sm"><div><p className="font-bold">{tx.label}</p><p className="mt-0.5 text-xs text-muted-foreground">{new Date(tx.createdAt).toLocaleDateString()}</p></div><span className={`font-mono-ui font-medium ${tx.amount >= 0 ? 'text-[#4c8569]' : 'text-[#a14f48]'}`}>{tx.amount >= 0 ? '+' : ''}{tx.amount}</span></div>)}</div></section>}{(form || requestForm) && <div className="fixed inset-0 z-50 grid place-items-center overflow-y-auto bg-[#24243b]/55 p-4">{form ? <div className="my-6 w-full max-w-md rounded-3xl bg-[#fffaf1] p-7"><div className="mb-5 flex justify-between"><div><p className="font-mono-ui text-[10px] tracking-[.2em] text-[#9a7a2b] uppercase">{editing ? 'Edit reward' : 'New reward'}</p><h2 className="font-display text-2xl font-bold">{editing ? 'Tune the promise' : 'Make it worth the wait'}</h2></div><button onClick={() => setForm(false)}><X /></button></div><form onSubmit={save} className="space-y-4"><label className="block text-sm font-bold">Reward name<input value={title} onChange={(e) => setTitle(e.target.value)} placeholder="Takeaway and a sunset walk" className="mt-2 w-full rounded-xl border border-[#d9cfbd] bg-[#fffdf8] px-4 py-3 outline-none focus:border-[#c4962b]" /></label><label className="block text-sm font-bold">Description<textarea value={description} onChange={(e) => setDescription(e.target.value)} rows={2} placeholder="The good kind of evening." className="mt-2 w-full resize-none rounded-xl border border-[#d9cfbd] bg-[#fffdf8] px-4 py-3 outline-none focus:border-[#c4962b]" /></label><label className="block text-sm font-bold">Coin cost<input type="number" min="1" value={cost} onChange={(e) => setCost(e.target.value)} className="mt-2 w-full rounded-xl border border-[#d9cfbd] bg-[#fffdf8] px-4 py-3 outline-none focus:border-[#c4962b]" /></label><Button type="submit" disabled={create.isPending || update.isPending} className="w-full">{create.isPending || update.isPending ? <Loader2 className="animate-spin" /> : editing ? 'Save changes' : 'Add to the shop'}</Button></form></div> : <div className="my-6 w-full max-w-md rounded-3xl bg-[#fffaf1] p-7"><div className="mb-5 flex justify-between"><div><p className="font-mono-ui text-[10px] tracking-[.2em] text-[#9a7a2b] uppercase">Request a reward</p><h2 className="font-display text-2xl font-bold">Name the thing</h2></div><button onClick={() => setRequestForm(false)}><X /></button></div><form onSubmit={sendRequest} className="space-y-4"><label className="block text-sm font-bold">What would you like?<input value={requestTitle} onChange={(e) => setRequestTitle(e.target.value)} placeholder="You cook dinner tonight" className="mt-2 w-full rounded-xl border border-[#d9cfbd] bg-[#fffdf8] px-4 py-3 outline-none focus:border-[#c4962b]" /></label><label className="block text-sm font-bold">A little context <span className="font-normal text-muted-foreground">(optional)</span><textarea value={requestDescription} onChange={(e) => setRequestDescription(e.target.value)} rows={2} placeholder="I’ll handle dishes." className="mt-2 w-full resize-none rounded-xl border border-[#d9cfbd] bg-[#fffdf8] px-4 py-3 outline-none focus:border-[#c4962b]" /></label><label className="block text-sm font-bold">Offer<input type="number" min="1" value={requestOffer} onChange={(e) => setRequestOffer(e.target.value)} className="mt-2 w-full rounded-xl border border-[#d9cfbd] bg-[#fffdf8] px-4 py-3 outline-none focus:border-[#c4962b]" /></label><Button type="submit" disabled={createRequest.isPending || !state.players.find((player) => player.id !== meId)} className="w-full">{createRequest.isPending ? <Loader2 className="animate-spin" /> : 'Send request'}</Button></form></div>}</div>}</>;
}

function TogetherPage({ state }: { state: GameState }) {
   const create = useCreateEncouragement(); const qc = useQueryClient(); const meId = localStorage.getItem('quest-road-player') ?? state.players[0]?.id ?? ''; const other = state.players.find((p) => p.id !== meId); const [message, setMessage] = useState(''); const send = (e: FormEvent) => { e.preventDefault(); if (!message.trim() || !other) return; create.mutate({ roomId: state.room.id, data: { fromId: meId, toId: other.id, message: message.trim() } }, { onSuccess: () => { setMessage(''); qc.invalidateQueries({ queryKey: getGetGameStateQueryKey(state.room.id) }); } }); }; return <><PageHeader eyebrow="Same road, different footsteps" title="Together" body="Notice the little things your teammate is doing. That is the whole point." /><div className="grid gap-5 lg:grid-cols-[1.1fr_.9fr]"><section className="grid gap-4 sm:grid-cols-2">{state.players.map((player) => { const quests = state.quests.filter((q) => q.ownerId === player.id); const done = quests.filter((q) => q.status === 'completed').length; return <article key={player.id} data-testid={`card-player-progress-${player.id}`} className="rounded-3xl border border-[#dfd3c1] bg-[#fffaf1] p-6"><div className="flex items-center gap-3"><Avatar player={player} size="lg" /><div><h2 className="font-display text-xl font-bold">{player.name}</h2><p className="text-xs text-muted-foreground">{player.streak} day streak</p></div></div><div className="mt-7 flex items-end justify-between"><div><p className="font-mono-ui text-3xl">{done}<span className="text-[#aaa192]">/{quests.length}</span></p><p className="text-xs font-bold text-muted-foreground">quests reached</p></div><div className="text-right"><p className="font-mono-ui text-lg text-[#ad7d1e]">{player.coins}</p><p className="text-xs font-bold text-muted-foreground">coins</p></div></div><div className="mt-4 h-2 overflow-hidden rounded-full bg-[#e6ddcf]"><div className="h-full rounded-full bg-[#579477] transition-all" style={{ width: `${quests.length ? done / quests.length * 100 : 0}%` }} /></div></article>; })}{state.players.length < 2 && <div className="rounded-3xl border border-dashed border-[#d7cbb8] bg-[#f8f1e5] p-6"><div className="grid h-12 w-12 place-items-center rounded-2xl bg-[#eee2d2] text-[#89806f]"><UsersRound /></div><h2 className="mt-4 font-display text-xl font-bold">One more seat</h2><p className="mt-2 text-sm leading-6 text-muted-foreground">Invite your person to unlock the shared view.</p></div>}</section><section className="rounded-3xl border border-[#dfd3c1] bg-[#fffaf1] p-6 sm:p-7"><div className="flex items-center gap-3"><div className="grid h-10 w-10 place-items-center rounded-xl bg-[#dce9e2] text-[#4e8069]"><MessageCircle className="h-5 w-5" /></div><div><h2 className="font-display text-xl font-bold">Send a little wind</h2><p className="text-xs text-muted-foreground">No likes. No performance. Just a note.</p></div></div>{other ? <form onSubmit={send} className="mt-5"><textarea value={message} onChange={(e) => setMessage(e.target.value)} rows={3} maxLength={300} placeholder={`“You’ve got this, ${other.name}.”`} data-testid="input-encouragement-message" className="w-full resize-none rounded-2xl border border-[#d9cfbd] bg-[#fffdf8] px-4 py-3 text-sm outline-none focus:border-[#579477]" /><div className="mt-3 flex items-center justify-between"><span className="text-xs text-muted-foreground">{message.length}/300</span><Button type="submit" disabled={!message.trim() || create.isPending} data-testid="button-send-encouragement">{create.isPending ? <Loader2 className="h-4 w-4 animate-spin" /> : 'Send note'} <ArrowRight className="h-4 w-4" /></Button></div></form> : <p className="mt-5 rounded-xl bg-[#f0e8da] p-4 text-sm leading-6 text-muted-foreground">Once your friend joins, this becomes your direct line to their trail.</p>}<div className="mt-8 border-t border-[#e8dfd1] pt-5"><h3 className="text-xs font-extrabold tracking-wide text-muted-foreground uppercase">Recent notes</h3><div className="mt-4 space-y-3">{state.encouragements.slice(0, 5).map((note) => { const from = state.players.find((p) => p.id === note.fromId); return <div key={note.id} data-testid={`card-encouragement-${note.id}`} className="rounded-xl bg-[#f0e8da] p-3"><div className="flex items-center gap-2"><Avatar player={from} size="sm" /><p className="text-xs font-bold">{from?.name ?? 'A friend'}</p><span className="ml-auto text-[10px] text-muted-foreground">{new Date(note.createdAt).toLocaleDateString()}</span></div><p className="mt-2 text-sm leading-5 text-[#585364]">{note.message}</p></div>; })}{state.encouragements.length === 0 && <p className="text-sm text-muted-foreground">The first note is yours to write.</p>}</div></div></section></div></>;
}

function SettingsPage({ state }: { state: GameState }) {
  const [copied, setCopied] = useState(false);
  const [copiedLink, setCopiedLink] = useState(false);
  const [location, setLocation] = useLocation();
  const copy = () => {
    navigator.clipboard?.writeText(state.room.code);
    setCopied(true);
    setTimeout(() => setCopied(false), 1800);
  };
  const copyLink = () => {
    navigator.clipboard?.writeText(inviteLink(state.room.id));
    setCopiedLink(true);
    setTimeout(() => setCopiedLink(false), 1800);
  };
  const leave = () => {
    localStorage.removeItem('quest-road-room');
    localStorage.removeItem('quest-road-player');
    setLocation('/');
  };
  return <><PageHeader eyebrow="Keep the compass close" title="Settings" body="A few details for this room and the people walking it." /><div className="grid max-w-3xl gap-5"><section className="rounded-3xl border border-[#dfd3c1] bg-[#fffaf1] p-6 sm:p-8"><div className="flex items-start gap-4"><div className="grid h-12 w-12 place-items-center rounded-2xl bg-[#eee2d2] text-[#6c6574]"><Landmark /></div><div className="flex-1"><p className="text-xs font-bold text-muted-foreground">Current room</p><h2 data-testid="text-room-name" className="mt-1 font-display text-2xl font-bold">{state.room.name}</h2><p className="mt-1 text-sm text-muted-foreground">Created {new Date(state.room.createdAt).toLocaleDateString()}</p><div className="mt-5 flex flex-wrap items-center gap-3"><span className="rounded-lg bg-[#eee2d2] px-3 py-2 font-mono-ui text-sm tracking-[.18em]">{state.room.code}</span><Button variant="ghost" onClick={copy} data-testid="button-copy-room-code"><Copy className="h-4 w-4" /> {copied ? 'Copied' : 'Copy code'}</Button><Button variant="ghost" onClick={copyLink} data-testid="button-copy-invite-link"><Link2 className="h-4 w-4" /> {copiedLink ? 'Link copied' : 'Copy invite link'}</Button></div></div></div></section><section className="rounded-3xl border border-[#dfd3c1] bg-[#fffaf1] p-6 sm:p-8"><div className="flex items-start gap-4"><div className="grid h-12 w-12 place-items-center rounded-2xl bg-[#dce9e2] text-[#4e8069]"><LockKeyhole /></div><div><h2 className="font-display text-xl font-bold">Private by design</h2><p className="mt-2 text-sm leading-6 text-muted-foreground">Quest Road is built for two. Your room is only accessible through its code, and shared state lives with your room on the server.</p></div></div></section><section className="rounded-3xl border border-[#efd4ce] bg-[#fff7f4] p-6 sm:p-8"><div className="flex items-start justify-between gap-4"><div><h2 className="font-display text-xl font-bold text-[#9f433e]">Leave this journey</h2><p className="mt-2 text-sm leading-6 text-[#855e59]">This clears the room convenience from this browser. It does not delete the shared room.</p></div><Button variant="danger" onClick={leave} data-testid="button-leave-room">Leave room</Button></div></section></div></>;
}

function RoomPage() {
  const { roomId = '' } = useParams<{ roomId: string }>(); const [, setLocation] = useLocation(); const roomQuery = useGetRoom(roomId, { query: { queryKey: getGetRoomQueryKey(roomId), refetchInterval: 8000 } }); const stateQuery = useGetGameState(roomId, { query: { queryKey: getGetGameStateQueryKey(roomId), refetchInterval: 8000 } }); const [copied, setCopied] = useState(false); useEffect(() => { if (roomId) localStorage.setItem('quest-road-room', roomId); }, [roomId]); if (roomQuery.isLoading) return <main className="min-h-[100dvh] bg-[#f3ecdf]"><LoadingState label="Opening your room..." /></main>; if (roomQuery.isError || !roomQuery.data) return <main className="min-h-[100dvh] bg-[#f3ecdf]"><ErrorState retry={() => roomQuery.refetch()} /></main>; const room = roomQuery.data; const copy = () => { navigator.clipboard?.writeText(room.code); setCopied(true); setTimeout(() => setCopied(false), 1800); }; if (room.status === 'waiting') return <main className="min-h-[100dvh] bg-[#24243b] px-5 py-6 text-[#fff7e8] sm:px-10"><header><Link href="/" className="flex items-center gap-3" data-testid="link-waiting-logo"><span className="grid h-10 w-10 place-items-center rounded-xl bg-[#f7ca56] text-[#24243b]"><Compass className="h-5 w-5" /></span><span className="font-display text-lg font-bold">Quest Road</span></Link></header><div className="mx-auto flex min-h-[calc(100dvh-100px)] max-w-xl items-center justify-center py-12"><section className="w-full animate-rise rounded-3xl bg-[#fff7e8] p-7 text-[#24243b] shadow-[0_24px_70px_rgba(9,10,28,.35)] sm:p-10"><div className="mb-8 flex items-center justify-between"><div><p className="font-mono-ui text-[10px] tracking-[.2em] text-[#9a7a2b] uppercase">Room created</p><h1 className="mt-2 font-display text-3xl font-bold">{room.name}</h1></div><div className="grid h-12 w-12 place-items-center rounded-2xl bg-[#f7ca56]"><Compass className="h-6 w-6" /></div></div><div className="rounded-2xl bg-[#302f48] p-5 text-center text-[#fff7e8]"><p className="text-xs font-bold text-[#aaa9ba]">Invite code</p><p data-testid="text-room-code" className="my-3 font-mono-ui text-3xl tracking-[.22em] text-[#f7ca56]">{room.code}</p><Button onClick={copy} variant="primary" className="mx-auto py-2 text-xs" data-testid="button-copy-waiting-code"><Copy className="h-3.5 w-3.5" /> {copied ? 'Copied to clipboard' : 'Copy code'}</Button></div><div className="my-8 flex items-center gap-4"><div className="flex -space-x-2"><Avatar player={room.host} size="lg" /></div><div className="h-px flex-1 bg-[#d9cfbd]" /><div className="grid h-10 w-10 place-items-center rounded-full border-2 border-dashed border-[#c8bba6] text-[#a69c8c]"><Plus className="h-4 w-4" /></div></div><div className="text-center"><h2 className="font-display text-xl font-bold">Waiting for your co-pilot</h2><p className="mt-2 text-sm leading-6 text-[#797388]">Send the code above. This page will notice when they arrive.</p><div className="mx-auto mt-5 flex w-fit items-center gap-2 rounded-full bg-[#eee2d2] px-3 py-1.5 text-xs font-bold text-[#797388]"><span className="h-2 w-2 animate-pulse-soft rounded-full bg-[#c4962b]" /> Listening for a friend</div></div><Button variant="ghost" onClick={() => setLocation('/')} className="mt-8 w-full" data-testid="button-back-home">Back to entry</Button></section></div></main>; if (stateQuery.isLoading) return <main className="min-h-[100dvh] bg-[#f3ecdf]"><LoadingState label="Loading both trails..." /></main>; if (stateQuery.isError || !stateQuery.data) return <main className="min-h-[100dvh] bg-[#f3ecdf]"><ErrorState retry={() => stateQuery.refetch()} /></main>; return <Shell state={stateQuery.data}><TodayPage state={stateQuery.data} /></Shell>;
}

function InviteRoomPage() {
  const { roomId = '' } = useParams<{ roomId: string }>();
  const [, setLocation] = useLocation();
  const roomQuery = useGetRoom(roomId, { query: { queryKey: getGetRoomQueryKey(roomId), refetchInterval: 8000 } });
  const join = useJoinRoom();
  const [name, setName] = useState('');
  const [error, setError] = useState('');
  const [copiedLink, setCopiedLink] = useState(false);
  useEffect(() => { if (roomId) localStorage.setItem('quest-road-room', roomId); }, [roomId]);
  if (roomQuery.isLoading) return <main className="min-h-[100dvh] bg-[#f3ecdf]"><LoadingState label="Opening the invite..." /></main>;
  if (roomQuery.isError || !roomQuery.data) return <main className="min-h-[100dvh] bg-[#f3ecdf]"><ErrorState retry={() => roomQuery.refetch()} /></main>;
  const room = roomQuery.data;
  const isHost = localStorage.getItem('quest-road-player') === room.host.id;
  const copyLink = () => {
    navigator.clipboard?.writeText(inviteLink(room.id));
    setCopiedLink(true);
    setTimeout(() => setCopiedLink(false), 1800);
  };
  const submit = (e: FormEvent) => {
    e.preventDefault();
    if (!name.trim()) return setError('Add your name so your friend knows who arrived.');
    join.mutate({ roomId, data: { code: room.code, playerName: name.trim() } }, {
      onSuccess: (joined) => { localStorage.setItem('quest-road-room', joined.id); localStorage.setItem('quest-road-player', joined.guest?.id ?? ''); setLocation(`/room/${joined.id}`); },
      onError: () => setError('That invite is no longer available. Ask your friend for a fresh room.'),
    });
  };
  if (room.status === 'playing') return <Shell><div className="mx-auto max-w-xl"><EmptyState icon={Compass} title="The journey is already underway" body="Your room is ready. Head to today to see what is waiting on the trail." action={<Link href="/today" data-testid="link-open-journey"><Button>Open the journey <ArrowRight className="h-4 w-4" /></Button></Link>} /></div></Shell>;
  return <main className="min-h-[100dvh] bg-[#24243b] px-5 py-6 text-[#fff7e8] sm:px-10"><header><Link href="/" className="flex items-center gap-3" data-testid="link-invite-logo"><span className="grid h-10 w-10 place-items-center rounded-xl bg-[#f7ca56] text-[#24243b] shadow-[0_4px_0_#c4962b]"><Compass className="h-5 w-5" /></span><span className="font-display text-lg font-bold">Quest Road</span></Link></header><div className="mx-auto flex min-h-[calc(100dvh-100px)] max-w-xl items-center justify-center py-12"><section className="w-full animate-rise rounded-3xl bg-[#fff7e8] p-7 text-[#24243b] shadow-[0_24px_70px_rgba(9,10,28,.35)] sm:p-10"><p className="font-mono-ui text-[10px] tracking-[.2em] text-[#9a7a2b] uppercase">{isHost ? 'Your room is ready' : 'You have been invited'}</p><h1 className="mt-2 font-display text-3xl font-bold">{room.name}</h1><p className="mt-3 text-sm leading-6 text-[#797388]">{isHost ? 'Share this invite link with your co-pilot. This page will update when they arrive.' : `${room.host.name} is saving you a seat.`}</p>{isHost ? <div className="mt-7 rounded-2xl bg-[#302f48] p-5 text-center text-[#fff7e8]"><p className="text-xs font-bold text-[#aaa9ba]">Invite code</p><p data-testid="text-room-code" className="my-3 font-mono-ui text-3xl tracking-[.22em] text-[#f7ca56]">{room.code}</p><div className="flex flex-col gap-2 sm:flex-row sm:justify-center"><Button onClick={copyLink} variant="primary" className="py-2 text-xs" data-testid="button-copy-invite-link"><Link2 className="h-3.5 w-3.5" /> {copiedLink ? 'Invite link copied' : 'Copy invite link'}</Button><Button onClick={() => { navigator.clipboard?.writeText(room.code); }} variant="ghost" className="border-[#ffffff30] text-[#fff7e8] py-2 text-xs" data-testid="button-copy-waiting-code"><Copy className="h-3.5 w-3.5" /> Copy code</Button></div><p className="mt-3 text-xs text-[#aaa9ba]">Listening for your friend to join</p></div> : <form onSubmit={submit} className="mt-7 space-y-4"><label className="block text-sm font-bold">Your name<input autoFocus value={name} onChange={(e) => setName(e.target.value)} placeholder="What should they call you?" data-testid="input-invite-player-name" className="mt-2 w-full rounded-xl border border-[#d9cfbd] bg-[#fbf5eb] px-4 py-3 outline-none focus:border-[#c4962b]" /></label>{error && <p data-testid="status-invite-error" className="rounded-lg bg-[#f3d5d0] px-3 py-2 text-sm font-semibold text-[#9f433e]">{error}</p>}<Button type="submit" disabled={join.isPending} data-testid="button-join-invite" className="w-full">{join.isPending ? <Loader2 className="h-4 w-4 animate-spin" /> : <>Join the journey <ArrowRight className="h-4 w-4" /></>}</Button></form>}<Button variant="ghost" onClick={() => setLocation('/')} className="mt-7 w-full" data-testid="button-back-invite">Back to entry</Button></section></div></main>;
}

function RoutedApp() {
  const [location] = useLocation(); const hasRoom = Boolean(localStorage.getItem('quest-road-room')); const shared = useSharedState(); const state = shared.data; const protectedPage = (page: ReactNode) => !hasRoom ? <Shell><MissingRoom /></Shell> : shared.isLoading ? <Shell><LoadingState /></Shell> : shared.isError || !state ? <Shell><ErrorState retry={() => shared.refetch()} /></Shell> : <Shell state={state}>{page}</Shell>;
  return <Switch><Route path="/" component={HomePage} /><Route path="/room/:roomId" component={InviteRoomPage} /><Route path="/today">{protectedPage(<TodayPageV2 state={state as GameState} />)}</Route><Route path="/map">{protectedPage(<MapPageV2 state={state as GameState} />)}</Route><Route path="/calendar">{protectedPage(<CalendarPage state={state as GameState} />)}</Route><Route path="/rewards">{protectedPage(<RewardsPageV2 state={state as GameState} />)}</Route><Route path="/together">{protectedPage(<TogetherPage state={state as GameState} />)}</Route><Route path="/settings">{protectedPage(<SettingsPage state={state as GameState} />)}</Route><Route component={NotFound} /></Switch>;
}

function App() {
  return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><ErrorBoundary resetKey={useLocation()[0]}><RoutedApp /></ErrorBoundary></WouterRouter><Toaster /></TooltipProvider></QueryClientProvider>;
}

export default App;